const AppMarkup = canvas.MarkupView(Model, Msg);

fn buildTree(arena: std.mem.Allocator, model: *const Model) !AppUi.Tree {
    main.registerIcons();
    var view = try AppMarkup.init(arena, main.app_markup);
    var ui = AppUi.init(arena);
    const node = view.build(&ui, model) catch |err| {
        if (err == error.MarkupBuild) {
            std.debug.print("app.native:{d}:{d}: {s}\n", .{ view.diagnostic.line, view.diagnostic.column, view.diagnostic.message });
        }
        return err;
    };
    return ui.finalize(node);
}

fn widgetName(widget: canvas.Widget) []const u8 {
    if (widget.semantics.label.len > 0) return widget.semantics.label;
    return widget.text;
}

fn findByText(widget: canvas.Widget, kind: canvas.WidgetKind, text: []const u8) ?canvas.Widget {
    return findNthByText(widget, kind, text, 0);
}

fn findTextContaining(widget: canvas.Widget, needle: []const u8) ?canvas.Widget {
    if (widget.kind == .text and std.mem.indexOf(u8, widget.text, needle) != null) return widget;
    for (widget.children) |child| {
        if (findTextContaining(child, needle)) |hit| return hit;
    }
    return null;
}

fn findNthByText(widget: canvas.Widget, kind: canvas.WidgetKind, text: []const u8, n: usize) ?canvas.Widget {
    var found: usize = 0;
    return findNthByTextInner(widget, kind, text, n, &found);
}

fn findNthByTextInner(widget: canvas.Widget, kind: canvas.WidgetKind, text: []const u8, n: usize, found: *usize) ?canvas.Widget {
    if (widget.kind == kind and std.mem.eql(u8, widgetName(widget), text)) {
        if (found.* == n) return widget;
        found.* += 1;
    }
    for (widget.children) |child| {
        if (findNthByTextInner(child, kind, text, n, found)) |hit| return hit;
    }
    return null;
}

fn expectByText(widget: canvas.Widget, kind: canvas.WidgetKind, text: []const u8) !canvas.Widget {
    return findByText(widget, kind, text) orelse {
        std.debug.print("no {t} with text \"{s}\" in the view\n", .{ kind, text });
        dumpTexts(widget, 0);
        return error.WidgetNotFound;
    };
}

fn expectModelChip(widget: canvas.Widget, text: []const u8) !canvas.Widget {
    if (findByText(widget, .button, text)) |hit| return hit;
    return expectByText(widget, .select, text);
}

fn expectChip(widget: canvas.Widget, text: []const u8) !canvas.Widget {
    return expectModelChip(widget, text);
}

fn dumpTexts(widget: canvas.Widget, depth: usize) void {
    const name = widgetName(widget);
    if (name.len > 0) {
        std.debug.print("{d} {t} [{s}]\n", .{ depth, widget.kind, name });
    }
    for (widget.children) |child| dumpTexts(child, depth + 1);
}

fn isPressable(kind: canvas.WidgetKind) bool {
    return kind == .button or kind == .list_item;
}

fn findPressableContaining(widget: canvas.Widget, text: []const u8) ?canvas.Widget {
    if (isPressable(widget.kind)) {
        if (std.mem.eql(u8, widgetName(widget), text)) return widget;
        if (findByText(widget, .text, text) != null) return widget;
    }
    for (widget.children) |child| {
        if (findPressableContaining(child, text)) |found| return found;
    }
    return null;
}

fn expectButton(widget: canvas.Widget, text: []const u8) !canvas.Widget {
    return findPressableContaining(widget, text) orelse {
        std.debug.print("no pressable containing \"{s}\"\n", .{text});
        dumpTexts(widget, 0);
        return error.WidgetNotFound;
    };
}

fn pressableAppearsBefore(widget: canvas.Widget, first: []const u8, second: []const u8) bool {
    var saw_first = false;
    return pressableAppearsBeforeInner(widget, first, second, &saw_first);
}

fn pressableAppearsBeforeInner(widget: canvas.Widget, first: []const u8, second: []const u8, saw_first: *bool) bool {
    if (isPressable(widget.kind) and std.mem.eql(u8, widgetName(widget), first)) {
        saw_first.* = true;
    } else if (isPressable(widget.kind) and std.mem.eql(u8, widgetName(widget), second)) {
        return saw_first.*;
    }
    for (widget.children) |child| {
        if (pressableAppearsBeforeInner(child, first, second, saw_first)) return true;
    }
    return false;
}

fn expectButtonMsg(tree: AppUi.Tree, text: []const u8, expected: Msg) !canvas.Widget {
    var n: usize = 0;
    while (findNthByText(tree.root, .button, text, n)) |widget| : (n += 1) {
        if (tree.msgForPointer(widget.id, .up)) |msg| {
            if (std.meta.eql(msg, expected)) return widget;
        }
    }
    std.debug.print("no button \"{s}\" dispatching that msg\n", .{text});
    dumpTexts(tree.root, 0);
    return error.WidgetNotFound;
}

fn expectSelectMsg(tree: AppUi.Tree, text: []const u8, expected: Msg) !canvas.Widget {
    var n: usize = 0;
    while (findNthByText(tree.root, .select, text, n)) |widget| : (n += 1) {
        if (tree.msgForPointer(widget.id, .up)) |msg| {
            if (std.meta.eql(msg, expected)) return widget;
        }
    }
    n = 0;
    while (findNthByText(tree.root, .button, text, n)) |widget| : (n += 1) {
        if (tree.msgForPointer(widget.id, .up)) |msg| {
            if (std.meta.eql(msg, expected)) return widget;
        }
    }
    std.debug.print("no select/button \"{s}\" dispatching that msg\n", .{text});
    dumpTexts(tree.root, 0);
    return error.WidgetNotFound;
}

fn expectNoContextMenu(widget: canvas.Widget) !void {
    if (!@hasField(canvas.Widget, "context_menu")) return;
    try testing.expectEqual(@as(usize, 0), widget.context_menu.len);
}

fn expectSessionContextMenu(tree: AppUi.Tree, row: canvas.Widget, session_id: u32) !void {
    if (!@hasField(canvas.Widget, "context_menu")) return error.ContextMenuUnsupported;
    try testing.expectEqual(@as(usize, 3), row.context_menu.len);
    try testing.expectEqualStrings("Rename", row.context_menu[0].label);
    try testing.expect(!row.context_menu[0].separator);
    try testing.expect(row.context_menu[1].separator);
    try testing.expectEqualStrings("Remove", row.context_menu[2].label);
    try testing.expect(!row.context_menu[2].separator);
    if (@hasDecl(@TypeOf(tree), "msgForContextMenu")) {
        try testing.expectEqual(Msg{ .rename_session = session_id }, tree.msgForContextMenu(row.id, 0).?);
        try testing.expectEqual(Msg{ .remove_session = session_id }, tree.msgForContextMenu(row.id, 2).?);
    }
}

fn expectFolderContextMenu(tree: AppUi.Tree, row: canvas.Widget, folder_id: u32) !void {
    if (!@hasField(canvas.Widget, "context_menu")) return error.ContextMenuUnsupported;
    try testing.expectEqual(@as(usize, 3), row.context_menu.len);
