    drainEffects(&model, &fx);

    try fx.feedLine(key, "{\"jsonrpc\":\"2.0\",\"method\":\"session/update\",\"params\":{\"sessionId\":\"acp-cmd-1\",\"update\":{\"sessionUpdate\":\"session_info_update\",\"title\":\"not commands\"}}}");
