fn findOpenTerminalSpawn(fx: *Effects) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (open_terminal.isTerminalArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn findOpenTerminalSpawnNamed(fx: *Effects, bin: []const u8) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.argv.len > 0 and std.mem.eql(u8, spawn.argv[0], bin) and open_terminal.isTerminalArgv(spawn.argv)) {
            return spawn;
        }
    }
    return null;
}

fn absOpenTerminalDir(tmp: testing.TmpDir, name: []const u8, buf: []u8) ![]const u8 {
    const path = try std.fmt.bufPrint(buf, "/tmp/faku-term-{s}-{s}", .{ tmp.sub_path, name });
    try std.Io.Dir.cwd().createDirPath(testing.io, path);
    return path;
}

test "open_terminal existing directory captures host terminal argv and leaves project_path" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try absOpenTerminalDir(tmp, "ok", &project_buf);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("open terminal session", .fx);
    model.selected = id;
    model.setSelectedProjectPath(project);
    try testing.expect(model.can_open_terminal());
    try testing.expect(model.can_reveal_folder());
    try testing.expect(!model.project_is_local());

    var tree = try buildTree(arena, &model);
    const terminal = try expectButtonMsg(tree, "Open in Terminal", .open_terminal);
    try testing.expect(pressableAppearsBefore(tree.root, "Reveal folder", "Open in Terminal"));
    try testing.expect(findByText(tree.root, .button, "Pick folder") == null);
    _ = try expectButtonMsg(tree, "Reveal folder", .reveal_folder);

    const before = model.selectedProjectPath();
    main.update(&model, tree.msgForPointer(terminal.id, .up).?, &fx);
    if (open_terminal.hostBin(.first) == null) {
        try testing.expectEqual(@as(usize, 0), fx.pendingSpawnCount());
        try testing.expectEqualStrings(open_terminal.hostMissingStatus(), model.window_status());
        try testing.expectEqualStrings(before, model.selectedProjectPath());
        return;
    }
    try testing.expect(model.open_terminal_live);
    try testing.expect(!model.has_window_status());
    const spawn = findOpenTerminalSpawn(&fx) orelse return error.MissingOpenTerminalSpawn;
    try testing.expectEqual(main.open_terminal_key, spawn.key);
    try testing.expect(spawn.key != main.reveal_folder_key);
    try testing.expect(spawn.key != main.pick_folder_key);
    try testing.expect(spawn.key != main.pick_image_key);
    try testing.expect(open_terminal.isTerminalArgv(spawn.argv));
    try testing.expect(!reveal_folder.isRevealArgv(spawn.argv));
    try testing.expect(!pick_folder.isPickerArgv(spawn.argv));
    try testing.expectEqualStrings(open_terminal.hostBin(.first).?, spawn.argv[0]);
    if (spawn.argv.len == 4) {
        try testing.expectEqualStrings(open_terminal.macos_app_flag, spawn.argv[1]);
        try testing.expectEqualStrings(open_terminal.macos_app, spawn.argv[2]);
        try testing.expectEqualStrings(project, spawn.argv[3]);
    } else if (spawn.argv.len == 3) {
        try testing.expectEqualStrings(open_terminal.windows_d_flag, spawn.argv[1]);
        try testing.expectEqualStrings(project, spawn.argv[2]);
    } else {
        try testing.expectEqual(@as(usize, 2), spawn.argv.len);
        try testing.expect(std.mem.startsWith(u8, spawn.argv[1], open_terminal.working_directory_prefix));
        try testing.expect(std.mem.endsWith(u8, spawn.argv[1], project));
    }
    try testing.expectEqualStrings("", spawn.stdin);
    try testing.expectEqualStrings(project, model.selectedProjectPath());
    try testing.expectEqualStrings(project, model.lastProjectPath());
    try testing.expect(!model.reveal_folder_live);
    try testing.expect(!model.pick_folder_live);
}

