test "dropLastPromptTurns keeps earlier prompts and other sessions" {
    var model = Model{};
    const other = model.addSession("other", .fx);
    const id = model.addSession("me", .fx);
    model.selected = id;
    _ = model.appendTurn(other, .user, "other user");
    _ = model.appendTurn(id, .user, "keep");
    _ = model.appendTurn(id, .assistant, "keep reply");
    _ = model.appendTurn(id, .user, "drop");
    _ = model.appendTurn(id, .assistant, "drop reply");
    _ = model.appendTurn(id, .tool, "drop tool");
    _ = model.appendTurn(id, .reasoning, "drop thought");
    _ = model.appendTurn(other, .assistant, "other asst");
    model.dropLastPromptTurns(id);
    try testing.expectEqual(@as(u32, 2), model.turnCount(id));
    try testing.expectEqual(@as(u32, 2), model.turnCount(other));
    try testing.expectEqualStrings("keep", lastUser(&model));
    model.dropLastPromptTurns(id);
    try testing.expectEqual(@as(u32, 0), model.turnCount(id));
    try testing.expectEqual(@as(u32, 2), model.turnCount(other));
    model.dropLastPromptTurns(id);
    try testing.expectEqual(@as(u32, 0), model.turnCount(id));
}

test "Send records the pre-commit HEAD; a later commit stays off the rewind target" {
    const allocator = testing.allocator;
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/rewind-git", .{tmp.sub_path[0..]});
    const expected = try initTestGitRepo(allocator, testing.io, project);
    defer allocator.free(expected);
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-rewind", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.task_state_loaded = true;
    model.setStoreDir(dir);
    model.store_io = testing.io;
    model.fx_available = true;
    model.fx_probe_started = true;
    model.setFxPath("fx");
    const id = model.addSession("rewind git", .fx);
    if (model.sessionById(id)) |session| session.setProjectPath(project);
    model.selected = id;

    main.update(&model, .{ .draft_edit = .{ .insert_text = "record this head" } }, &fx);
    main.update(&model, .send, &fx);
    try testing.expect(model.is_streaming());
    const at_send = model.sessionById(id).?;
    try testing.expectEqual(@as(usize, 1), at_send.rewind_ref_count);
    try testing.expectEqualStrings(expected, at_send.rewindRefs()[0].sha());
    try testing.expectEqualStrings(rewind.recorded_ref, at_send.rewindRefs()[0].refName());
    try testing.expect(at_send.rewindRefs()[0].recorded_at > 0);
    try testing.expect(rewind.isStoredSha(at_send.worktreeSnapshotSha()));
    try testing.expect(!std.mem.eql(u8, expected, at_send.worktreeSnapshotSha()));
    try testing.expectEqual(@as(usize, 0), at_send.worktreeTurnEndSha().len);
    try testing.expectEqual(@as(usize, 0), at_send.worktreeTurnDiffSha().len);

    try dirtyAndAdvanceRepo(allocator, testing.io, project, "agent commit\n");
    var after_buf: [rewind.max_sha]u8 = undefined;
    const after = rewind.revParseHead(allocator, testing.io, project, &after_buf) orelse return error.GitHead;
    try testing.expect(!std.mem.eql(u8, expected, after));

    try fx.feedExit(main.fx_ask_key, 0);
    drainEffects(&model, &fx);
    try testing.expect(!model.is_streaming());

    const live = model.sessionById(id).?;
    try testing.expectEqual(@as(usize, 1), live.rewind_ref_count);
    try testing.expectEqualStrings(expected, live.rewindRefs()[0].sha());
    try testing.expectEqualStrings(rewind.recorded_ref, live.rewindRefs()[0].refName());
    try testing.expect(rewind.isStoredSha(live.worktreeTurnEndSha()));
    try testing.expect(!std.mem.eql(u8, live.worktreeSnapshotSha(), live.worktreeTurnEndSha()));
    try testing.expect(rewind.isStoredSha(live.worktreeTurnDiffSha()));
    try testing.expectEqualStrings(live.worktreeSnapshotSha(), live.worktreeTurnDiffSha());

    var loaded = Model{};
    loaded.setStoreDir(dir);
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, allocator, testing.io));
    try testing.expectEqualStrings(expected, loaded.session_store[0].rewindRefs()[0].sha());
    try testing.expect(rewind.isStoredSha(loaded.session_store[0].worktreeSnapshotSha()));
    try testing.expectEqualStrings(live.worktreeTurnEndSha(), loaded.session_store[0].worktreeTurnEndSha());
    try testing.expectEqualStrings(live.worktreeTurnDiffSha(), loaded.session_store[0].worktreeTurnDiffSha());
    store.hydrateSession(&loaded, id, allocator, testing.io);
    try testing.expectEqualStrings(expected, loaded.session_store[0].rewindRefs()[0].sha());
    try testing.expectEqualStrings(live.worktreeSnapshotSha(), loaded.session_store[0].worktreeSnapshotSha());
    try testing.expectEqualStrings(live.worktreeTurnEndSha(), loaded.session_store[0].worktreeTurnEndSha());
    try testing.expectEqualStrings(live.worktreeTurnDiffSha(), loaded.session_store[0].worktreeTurnDiffSha());
}

test "Send worktree snapshot includes dirty and untracked; overwrite keeps latest" {
    const allocator = testing.allocator;
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/snap-send", .{tmp.sub_path[0..]});
    const head = try initTestGitRepo(allocator, testing.io, project);
    defer allocator.free(head);

    var readme_buf: [std.fs.max_path_bytes]u8 = undefined;
    const readme = try std.fmt.bufPrint(&readme_buf, "{s}{s}README", .{ project, std.fs.path.sep_str });
    try std.Io.Dir.cwd().writeFile(testing.io, .{ .sub_path = readme, .data = "dirty\n" });
    var extra_buf: [std.fs.max_path_bytes]u8 = undefined;
    const extra = try std.fmt.bufPrint(&extra_buf, "{s}{s}untracked.txt", .{ project, std.fs.path.sep_str });
    try std.Io.Dir.cwd().writeFile(testing.io, .{ .sub_path = extra, .data = "new\n" });

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    model.fx_available = true;
    model.fx_probe_started = true;
    model.setFxPath("fx");
    const id = model.addSession("snap send", .fx);
    if (model.sessionById(id)) |session| session.setProjectPath(project);
    model.selected = id;

    main.update(&model, .{ .draft_edit = .{ .insert_text = "snap this tree" } }, &fx);
    main.update(&model, .send, &fx);
    const first_owned = try allocator.dupe(u8, model.sessionById(id).?.worktreeSnapshotSha());
    defer allocator.free(first_owned);
    try testing.expect(rewind.isStoredSha(first_owned));
    try testing.expect(!std.mem.eql(u8, head, first_owned));
    try testing.expectEqual(@as(usize, 0), model.sessionById(id).?.worktreeTurnEndSha().len);
    try testing.expectEqual(@as(usize, 0), model.sessionById(id).?.worktreeTurnDiffSha().len);
    const names = try runGitCapture(allocator, testing.io, &.{ "git", "-C", project, "diff", "--name-status", head, first_owned });
    defer allocator.free(names);
    try testing.expect(std.mem.indexOf(u8, names, "README") != null);
    try testing.expect(std.mem.indexOf(u8, names, "untracked.txt") != null);

    try fx.feedExit(main.fx_ask_key, 0);
    drainEffects(&model, &fx);
    try testing.expect(rewind.isStoredSha(model.sessionById(id).?.worktreeTurnEndSha()));
    try testing.expectEqualStrings(first_owned, model.sessionById(id).?.worktreeSnapshotSha());
    try testing.expectEqualStrings(first_owned, model.sessionById(id).?.worktreeTurnDiffSha());

    try std.Io.Dir.cwd().writeFile(testing.io, .{ .sub_path = extra, .data = "changed\n" });
    main.update(&model, .{ .draft_edit = .{ .insert_text = "snap again" } }, &fx);
    main.update(&model, .send, &fx);
    const second = model.sessionById(id).?.worktreeSnapshotSha();
    try testing.expect(rewind.isStoredSha(second));
    try testing.expect(!std.mem.eql(u8, first_owned, second));
    try testing.expectEqual(@as(usize, 0), model.sessionById(id).?.worktreeTurnEndSha().len);
    try testing.expectEqual(@as(usize, 0), model.sessionById(id).?.worktreeTurnDiffSha().len);
}

