        try testing.expect(!checkpoint.updateFakuRef(
            allocator,
            testing.io,
            ".zig-cache/tmp/faku-ref-no-git",
            "refs/faku/session-1-turn-1",
            sha,
        ));
        try testing.expectEqualStrings(sha, session.worktreeSnapshotSha());
    } else return error.MissingSession;
}

