test "selecting a session focuses the composer; rename and search do not" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    const port_id = model.session_store[0].id;
    const auth_id = model.session_store[1].id;
    try testing.expectEqual(port_id, model.selected);
    try testing.expect(!model.composer_active);
    try testing.expect(!model.palette_open);
    try testing.expectEqual(@as(u32, 0), model.editing_session_id);
    try testing.expectEqual(@as(u32, 0), model.editing_folder_id);

    var tree = try buildTree(arena, &model);
    const auth_row = try expectButton(tree.root, "fix auth listener");
    try testing.expectEqual(Msg{ .select = auth_id }, tree.msgForPointer(auth_row.id, .up).?);
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expectEqualStrings("Do anything...", composer.placeholder);
        try testing.expect(!composer.autofocus);
    } else return error.WidgetNotFound;
    _ = try expectByText(tree.root, .button, "Copy session");

    main.update(&model, tree.msgForPointer(auth_row.id, .up).?, &fx);
    try testing.expectEqual(auth_id, model.selected);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expect(model.composer_active);
    try testing.expectEqual(@as(u32, 0), model.editing_session_id);

    tree = try buildTree(arena, &model);
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expect(composer.autofocus);
    } else return error.WidgetNotFound;
    _ = try expectByText(tree.root, .button, "Copy session");

    // Second click on the selected row starts rename and must not steal
    // into the composer.
    const auth_again = try expectButton(tree.root, "fix auth listener");
    try testing.expectEqual(Msg{ .select = auth_id }, tree.msgForPointer(auth_again.id, .up).?);
    main.update(&model, tree.msgForPointer(auth_again.id, .up).?, &fx);
    try testing.expectEqual(auth_id, model.selected);
    try testing.expectEqual(auth_id, model.editing_session_id);
    try testing.expect(!model.composer_active);

    tree = try buildTree(arena, &model);
    if (findByPlaceholder(tree.root, .text_field, "untitled")) |field| {
        try testing.expect(field.autofocus);
    } else return error.WidgetNotFound;
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expect(!composer.autofocus);
    } else return error.WidgetNotFound;

    main.update(&model, .stop, &fx);
    try testing.expectEqual(@as(u32, 0), model.editing_session_id);
    try testing.expectEqual(auth_id, model.selected);

    main.update(&model, .start_search, &fx);
    try testing.expect(model.palette_open);
    try testing.expect(!model.composer_active);
    main.update(&model, .{ .search_edit = .{ .insert_text = "auth" } }, &fx);
    try testing.expect(model.palette_open);
    try testing.expect(!model.composer_active);
    try testing.expectEqual(auth_id, model.selected);

    tree = try buildTree(arena, &model);
    if (findByKind(tree.root, .search_field)) |field| {
        try testing.expectEqualStrings("Search", field.placeholder);
        try testing.expect(field.autofocus);
    } else return error.WidgetNotFound;
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expect(!composer.autofocus);
    } else return error.WidgetNotFound;

    main.update(&model, .stop, &fx);
    try testing.expect(!model.palette_open);
    try testing.expectEqual(auth_id, model.selected);

    main.update(&model, .new_folder, &fx);
    const folder_id = model.folder_store[0].id;
    main.update(&model, .{ .assign_selected = folder_id }, &fx);
    try testing.expectEqual(folder_id, model.sessionById(auth_id).?.folder_id);
    try testing.expectEqual(@as(u32, 0), model.editing_folder_id);
    try testing.expectEqual(auth_id, model.selected);

    main.update(&model, .{ .assign_selected = folder_id }, &fx);
    try testing.expectEqual(folder_id, model.editing_folder_id);
    try testing.expectEqual(auth_id, model.selected);
    try testing.expect(!model.composer_active);

    tree = try buildTree(arena, &model);
    if (findByPlaceholder(tree.root, .text_field, "New folder")) |field| {
        try testing.expect(field.autofocus);
    } else return error.WidgetNotFound;
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expect(!composer.autofocus);
    } else return error.WidgetNotFound;

    main.update(&model, .stop, &fx);
    try testing.expectEqual(@as(u32, 0), model.editing_folder_id);

    // History back is a normal select, so it uses the same autofocus edge.
    try testing.expect(model.can_go_back());
    main.update(&model, .history_back, &fx);
    try testing.expectEqual(port_id, model.selected);
    try testing.expectEqualStrings("port waku to zig", model.selected_title());
    try testing.expect(model.composer_active);
    try testing.expectEqual(@as(u32, 0), model.editing_session_id);
    try testing.expectEqual(@as(u32, 0), model.editing_folder_id);

    tree = try buildTree(arena, &model);
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expect(composer.autofocus);
    } else return error.WidgetNotFound;
    _ = try expectByText(tree.root, .button, "Copy session");
}

test "cmd-[ / cmd-] and ctrl-[ / ctrl-] walk session history via onKey" {
    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    try testing.expectEqualStrings("port waku to zig", model.selected_title());
    try testing.expect(!model.can_go_back());
    try testing.expect(!model.can_go_forward());

    main.update(&model, .{ .select = model.session_store[1].id }, &fx);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expect(model.can_go_back());
    try testing.expect(!model.can_go_forward());

    // Composer typing: plain [ / ] stay draft text, not history.
    main.update(&model, .{ .draft_edit = .{ .insert_text = "[" } }, &fx);
    try testing.expectEqualStrings("[", model.draft());
    const plain_back = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "[" };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(plain_back));
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expectEqualStrings("[", model.draft());

    const plain_forward = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "]" };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(plain_forward));
    try testing.expectEqualStrings("fix auth listener", model.selected_title());

    const cmd_back = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "[",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.history_back, keys.onKey(cmd_back).?);
    main.update(&model, keys.onKey(cmd_back).?, &fx);
    try testing.expectEqualStrings("port waku to zig", model.selected_title());
    try testing.expect(!model.can_go_back());
    try testing.expect(model.can_go_forward());

    main.update(&model, keys.onKey(cmd_back).?, &fx);
    try testing.expectEqualStrings("port waku to zig", model.selected_title());
    try testing.expect(!model.can_go_back());

    const cmd_forward = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "]",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.history_forward, keys.onKey(cmd_forward).?);
    main.update(&model, keys.onKey(cmd_forward).?, &fx);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expect(model.can_go_back());
    try testing.expect(!model.can_go_forward());

    main.update(&model, keys.onKey(cmd_forward).?, &fx);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expect(!model.can_go_forward());

    const ctrl_back = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "[",
        .modifiers = .{ .control = true },
    };
    try testing.expectEqual(Msg.history_back, keys.onKey(ctrl_back).?);
    main.update(&model, keys.onKey(ctrl_back).?, &fx);
    try testing.expectEqualStrings("port waku to zig", model.selected_title());

    const ctrl_forward = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "]",
        .modifiers = .{ .control = true },
    };
    try testing.expectEqual(Msg.history_forward, keys.onKey(ctrl_forward).?);
    main.update(&model, keys.onKey(ctrl_forward).?, &fx);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());

    const escape = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "escape" };
    try testing.expectEqual(Msg.stop, keys.onKey(escape).?);
}

test "plain tab and super-tab stay unbound; ctrl-tab opens the session switcher" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    const port = model.session_store[0].id;
    const auth = model.session_store[1].id;
    try testing.expectEqual(port, model.selected);
    try testing.expect(!model.switcher_open);

    const plain_tab = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "tab" };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(plain_tab));

    const super_tab = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "tab",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(super_tab));

    const ctrl_super_tab = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "tab",
        .modifiers = .{ .control = true, .super = true },
    };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(ctrl_super_tab));

    const ctrl_tab = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "tab",
        .modifiers = .{ .control = true },
    };
    try testing.expectEqual(Msg.switcher_forward, keys.onKey(ctrl_tab).?);
    main.update(&model, keys.onKey(ctrl_tab).?, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(@as(u32, 2), model.switcher_count);
    try testing.expectEqual(port, model.switcher_ids[0]);
    try testing.expectEqual(auth, model.switcher_ids[1]);
    try testing.expectEqual(@as(u32, 1), model.switcher_highlight);
    try testing.expectEqual(port, model.selected);

    var tree = try buildTree(arena, &model);
    const dialog = findByKind(tree.root, .dialog) orelse return error.WidgetNotFound;
    try testing.expectEqualStrings("Switch session", widgetName(dialog));
    const auth_row = try expectButton(dialog, "fix auth listener");
    try testing.expectEqual(Msg{ .switcher_pick = auth }, tree.msgForPointer(auth_row.id, .up).?);
    _ = try expectByText(dialog, .button, "Switch");

    main.update(&model, keys.onKey(ctrl_tab).?, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(@as(u32, 0), model.switcher_highlight);
    try testing.expectEqual(port, model.selected);

    const third = model.addSession("third started", .fx);
    _ = model.appendTurn(third, .user, "hello");
    main.update(&model, .switcher_cancel, &fx);
    try testing.expect(!model.switcher_open);
    try testing.expectEqual(port, model.selected);

    const ctrl_shift_tab = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "Tab",
        .modifiers = .{ .control = true, .shift = true },
    };
    try testing.expectEqual(Msg.switcher_backward, keys.onKey(ctrl_shift_tab).?);
    main.update(&model, keys.onKey(ctrl_shift_tab).?, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(@as(u32, 3), model.switcher_count);
    try testing.expectEqual(third, model.switcher_ids[2]);
    try testing.expectEqual(@as(u32, 2), model.switcher_highlight);
    try testing.expectEqual(port, model.selected);

    main.update(&model, keys.onKey(ctrl_shift_tab).?, &fx);
    try testing.expectEqual(@as(u32, 1), model.switcher_highlight);
    try testing.expectEqual(port, model.selected);

    main.update(&model, .{ .switcher_pick = auth }, &fx);
    try testing.expect(!model.switcher_open);
    try testing.expectEqual(auth, model.selected);

    main.update(&model, keys.onKey(ctrl_tab).?, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(auth, model.selected);
    const before = model.selected;
    const escape = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "escape" };
    try testing.expectEqual(Msg.stop, keys.onKey(escape).?);
    main.update(&model, keys.onKey(escape).?, &fx);
    try testing.expect(!model.switcher_open);
    try testing.expectEqual(before, model.selected);

    main.update(&model, keys.onKey(ctrl_tab).?, &fx);
    try testing.expect(model.switcher_open);
    const highlighted = model.switcher_ids[model.switcher_highlight];
    main.update(&model, .switcher_confirm, &fx);
    try testing.expect(!model.switcher_open);
    try testing.expectEqual(highlighted, model.selected);

    tree = try buildTree(arena, &model);
    try testing.expect(findByKind(tree.root, .dialog) == null);
}

test "ctrl-tab includes the current untitled session and caps the snapshot at ten" {
    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    const port = model.session_store[0].id;
    main.update(&model, .new_session, &fx);
    const draft = model.selected;
    try testing.expect(model.sessionById(draft).?.untitled);
    try testing.expect(!model.sessionById(draft).?.hasStarted());

    main.update(&model, .switcher_forward, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(@as(u32, 3), model.switcher_count);
    try testing.expectEqual(draft, model.switcher_ids[0]);
    try testing.expectEqual(port, model.switcher_ids[1]);
    try testing.expectEqual(@as(u32, 1), model.switcher_highlight);
    try testing.expectEqual(draft, model.selected);

    main.update(&model, .switcher_cancel, &fx);
    model.clearSessions();
    var n: u32 = 0;
    while (n < 12) : (n += 1) {
        var title_buf: [32]u8 = undefined;
        const title = std.fmt.bufPrint(&title_buf, "started {d}", .{n}) catch unreachable;
        const id = model.addSession(title, .fx);
        _ = model.appendTurn(id, .user, "hi");
        if (n == 0) model.selected = id;
    }
    try testing.expectEqual(@as(u32, 12), model.session_count);
    main.update(&model, .switcher_forward, &fx);
    try testing.expect(model.switcher_open);
    try testing.expectEqual(main.switcher_cap, model.switcher_count);
    try testing.expectEqual(model.selected, model.switcher_ids[0]);
