}

test "cmd-b and ctrl-b toggle sidebar collapse via onKey" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    try testing.expect(!model.sidebar_collapsed);
    try testing.expect(model.sidebar_expanded());

    // Composer typing: plain b is draft text, not collapse.
    main.update(&model, .{ .draft_edit = .{ .insert_text = "b" } }, &fx);
    try testing.expectEqualStrings("b", model.draft());
    const plain_b = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "b" };
    try testing.expectEqual(@as(?Msg, null), keys.onKey(plain_b));
    try testing.expect(!model.sidebar_collapsed);
    try testing.expectEqualStrings("b", model.draft());

    var tree = try buildTree(arena, &model);
    const collapse = try expectButton(tree.root, "Collapse sidebar");
    try testing.expectEqual(Msg.toggle_sidebar, tree.msgForPointer(collapse.id, .up).?);

    const cmd_b = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "b",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.toggle_sidebar, keys.onKey(cmd_b).?);
    main.update(&model, keys.onKey(cmd_b).?, &fx);
    try testing.expect(model.sidebar_collapsed);
    try testing.expect(!model.sidebar_expanded());
    try testing.expectEqual(main.sidebar_rail_width / main.window_width, model.sidebar_split);
    try testing.expectEqual(main.sidebar_rail_width, model.sidebar_pane_min());

    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "Today") == null);
    try testing.expect(findPressableContaining(tree.root, "Search") == null);
    try testing.expect(findPressableContaining(tree.root, "New Task") == null);
    _ = try expectButton(tree.root, "Expand sidebar");

    main.update(&model, keys.onKey(cmd_b).?, &fx);
    try testing.expect(!model.sidebar_collapsed);
    try testing.expectEqual(main.sidebar_default_width / main.window_width, model.sidebar_split);

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Today");
    _ = try expectButton(tree.root, "Search");
    _ = try expectButton(tree.root, "New Task");
    _ = try expectButton(tree.root, "Collapse sidebar");

    const ctrl_b = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "B",
        .modifiers = .{ .control = true },
    };
    try testing.expectEqual(Msg.toggle_sidebar, keys.onKey(ctrl_b).?);
    main.update(&model, keys.onKey(ctrl_b).?, &fx);
    try testing.expect(model.sidebar_collapsed);

    const cmd_n = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "n",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.new_session, keys.onKey(cmd_n).?);
    const cmd_back = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "[",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.history_back, keys.onKey(cmd_back).?);
}

test "cmd-b persist extras stay merge-only" {
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-sidebar-cmd-b", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    const cmd_b = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "b",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.toggle_sidebar, keys.onKey(cmd_b).?);

    var missing = main.initialModel();
    missing.task_state_loaded = true;
    missing.setStoreDir(dir);
    missing.store_io = testing.io;
    main.update(&missing, keys.onKey(cmd_b).?, &fx);
    try testing.expect(missing.sidebar_collapsed);
    var missing_path: [std.fs.max_path_bytes]u8 = undefined;
    try testing.expectError(error.FileNotFound, std.Io.Dir.cwd().readFileAlloc(testing.io, store.catalogPath(dir, &missing_path).?, testing.allocator, .limited(64)));

    var source = main.initialModel();
    source.task_state_loaded = true;
    source.setStoreDir(dir);
    source.store_io = testing.io;
    try store.saveSession(&source, source.session_store[0].id, testing.allocator, testing.io);
    try store.saveSession(&source, source.session_store[1].id, testing.allocator, testing.io);
    source.sidebar_last_width = 320;
    source.sidebar_split = 320 / main.window_width;
    main.update(&source, keys.onKey(cmd_b).?, &fx);
    try testing.expect(source.sidebar_collapsed);

    var loaded = Model{};
    loaded.setStoreDir(dir);
    loaded.store_io = testing.io;
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, testing.allocator, testing.io));
    try testing.expect(loaded.sidebar_collapsed);
    try testing.expectEqual(@as(u32, 2), loaded.session_count);
    try testing.expectEqual(source.session_store[0].id, loaded.session_store[0].id);
    try testing.expectEqual(source.session_store[1].id, loaded.session_store[1].id);
    try testing.expectEqual(@as(u32, 320), loaded.sidebarWidthPixels());
    try testing.expectEqual(main.sidebar_rail_width / main.window_width, loaded.sidebar_split);

    main.update(&loaded, keys.onKey(cmd_b).?, &fx);
    try testing.expect(!loaded.sidebar_collapsed);

    var restored = Model{};
    restored.setStoreDir(dir);
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&restored, testing.allocator, testing.io));
    try testing.expect(!restored.sidebar_collapsed);
    try testing.expectEqual(@as(u32, 2), restored.session_count);
    try testing.expectEqual(source.session_store[0].id, restored.session_store[0].id);
    try testing.expectEqual(source.session_store[1].id, restored.session_store[1].id);
    try testing.expectEqual(@as(u32, 320), restored.sidebarWidthPixels());
}

test "toggle right panel opens and closes the Files pane" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    try testing.expect(!model.right_panel_open);
    try testing.expectEqual(@as(f32, 1.0), model.right_panel_split);
    try testing.expectEqual(@as(u32, 184), model.rightPanelWidthPixels());

    var tree = try buildTree(arena, &model);
    const show = try expectButton(tree.root, "Show right panel");
    try testing.expectEqual(Msg.toggle_right_panel, tree.msgForPointer(show.id, .up).?);
    try testing.expect(findByText(tree.root, .text, "Files") == null);
    try testing.expect(findByText(tree.root, .text, "No project open") == null);

    main.update(&model, .toggle_right_panel, &fx);
    try testing.expect(model.right_panel_open);
    try testing.expect(model.right_panel_split < 1.0);
    try testing.expect(model.right_panel_no_project());

    tree = try buildTree(arena, &model);
    const files_tab = try expectButtonMsg(tree, "Files", .set_right_panel_tab_files);
    try testing.expect(files_tab.state.selected);
    const diff_tab = try expectButtonMsg(tree, "Diff", .set_right_panel_tab_diff);
    try testing.expect(!diff_tab.state.selected);
    try testing.expect(!(try expectButtonMsg(tree, "Browser", .set_right_panel_tab_browser)).state.selected);
    try testing.expect(!(try expectButtonMsg(tree, "Terminal", .set_right_panel_tab_terminal)).state.selected);
    try testing.expect(!(try expectButtonMsg(tree, "Background", .set_right_panel_tab_background)).state.selected);
    _ = try expectByText(tree.root, .text, "No project open");
    _ = try expectByText(tree.root, .text, "Open a project to browse its files");
    const hide = try expectButton(tree.root, "Hide right panel");
    try testing.expect(tree.msgForPointer(hide.id, .up).? == .hide_right_panel or tree.msgForPointer(hide.id, .up).? == .toggle_right_panel);

    main.update(&model, .hide_right_panel, &fx);
    try testing.expect(!model.right_panel_open);
    try testing.expectEqual(@as(f32, 1.0), model.right_panel_split);

    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "Files") == null);
    try testing.expect(findByText(tree.root, .text, "No project open") == null);

    main.update(&model, .show_right_panel, &fx);
    try testing.expect(model.right_panel_open);
    main.update(&model, .show_right_panel, &fx);
    try testing.expect(model.right_panel_open);
}

test "right panel Files list reads file_mention cache and derived dirs" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try absCopyProjectDir(tmp, "files-pane", &project_buf);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("files pane", .fx);
    model.selected = id;
    model.setSelectedProjectPath(project);
    defer right_panel.clearFilePreview(&model);

    main.update(&model, .show_right_panel, &fx);
    try testing.expect(model.right_panel_open);
    try testing.expect(!model.right_panel_no_project());
    try testing.expectEqual(@as(usize, 0), model.right_panel_file_rows(arena).len);

    var tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "No project open") == null);
    try testing.expect(findByText(tree.root, .text, "main.zig") == null);

    file_mention.applyStdoutPaths(&model,
        \\src/main.zig
        \\src/composer.zig
        \\README.md
    );
    var src_dir_buf: [320]u8 = undefined;
    const src_dir = try std.fmt.bufPrint(&src_dir_buf, "{s}/src", .{project});
    try std.Io.Dir.cwd().createDirPath(testing.io, src_dir);
    var main_path_buf: [320]u8 = undefined;
    const main_path = try std.fmt.bufPrint(&main_path_buf, "{s}/src/main.zig", .{project});
    try std.Io.Dir.cwd().writeFile(testing.io, .{
        .sub_path = main_path,
        .data = "pub fn main() void {}\n",
    });
    {
        const rows = model.right_panel_file_rows(arena);
        try testing.expectEqual(@as(usize, 2), rows.len);
        try testing.expectEqualStrings("README.md", rows[0].path);
        try testing.expect(rows[0].is_file);
        try testing.expect(!rows[0].expanded);
        try testing.expectEqualStrings("src/", rows[1].path);
        try testing.expect(!rows[1].is_file);
        try testing.expect(!rows[1].expanded);
        try testing.expectEqual(file_mention.file_mention_dir_id_base, rows[1].id);
    }

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "README.md");
    _ = try expectByText(tree.root, .text, "src");
    try testing.expect(findByText(tree.root, .text, "main.zig") == null);
    try testing.expect(findByText(tree.root, .text, "composer.zig") == null);
    const dir_row = try expectButton(tree.root, "src/");
    try testing.expectEqual(Msg{ .toggle_right_panel_dir = file_mention.file_mention_dir_id_base }, tree.msgForPointer(dir_row.id, .up).?);

    main.update(&model, .{ .toggle_right_panel_dir = file_mention.file_mention_dir_id_base }, &fx);
    {
        const rows = model.right_panel_file_rows(arena);
        try testing.expectEqual(@as(usize, 4), rows.len);
        try testing.expectEqualStrings("README.md", rows[0].path);
        try testing.expectEqualStrings("src/", rows[1].path);
        try testing.expect(rows[1].expanded);
        try testing.expectEqualStrings("src/composer.zig", rows[2].path);
        try testing.expectEqualStrings("src/main.zig", rows[3].path);
        try testing.expect(rows[3].is_file);
        try testing.expectEqual(@as(u32, 1), rows[3].id);
    }

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "main.zig");
    _ = try expectByText(tree.root, .text, "composer.zig");
    const file_row = try expectButton(tree.root, "src/main.zig");
    try testing.expectEqual(Msg{ .open_right_panel_file = 1 }, tree.msgForPointer(file_row.id, .up).?);

    main.update(&model, .{ .open_right_panel_file = 1 }, &fx);
    try testing.expect(findOpenEditorSpawn(&fx) == null);
    try testing.expect(model.right_panel_file_preview_open());
    try testing.expectEqualStrings("src/main.zig", model.file_preview_path());
    try testing.expectEqualStrings("pub fn main() void {}\n", model.file_preview_body());
    try testing.expectEqualStrings("zig", model.file_preview_language());
    {
        const lines = model.file_preview_line_rows(arena);
        try testing.expectEqual(@as(usize, 1), lines.len);
        try testing.expectEqual(@as(u32, 1), lines[0].id);
        try testing.expectEqualStrings("1", lines[0].n_label);
        try testing.expectEqualStrings("pub fn main() void {}", lines[0].text);
    }
    {
        const preview_rows = model.right_panel_file_rows(arena);
        try testing.expect(preview_rows[3].selected);
    }

    tree = try buildTree(arena, &model);
    const open_editor_btn = try expectButton(tree.root, "Open in editor");
    try testing.expectEqual(Msg.open_right_panel_file_editor, tree.msgForPointer(open_editor_btn.id, .up).?);
    const close_preview = try expectButton(tree.root, "Close");
    try testing.expectEqual(Msg.close_right_panel_file_preview, tree.msgForPointer(close_preview.id, .up).?);
    const edit_btn = try expectButtonMsg(tree, "Edit", .open_right_panel_file_edit);
    _ = edit_btn;
    _ = try expectButtonMsg(tree, "Reload", .file_preview_reload);
    try testing.expect(findByText(tree.root, .button, "Save") == null);
    try testing.expect(findByText(tree.root, .text, "Unsaved") == null);
    const preview_source = findTextContaining(tree.root, "pub fn main() void {}") orelse {
        dumpTexts(tree.root, 0);
        return error.WidgetNotFound;
    };
    try testing.expectEqualStrings("pub fn main() void {}\n", preview_source.text);
    try testing.expect(preview_source.codeLineNumberDigits() > 0);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "<code source=\"{file_preview_body}\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "language=\"zig\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "line-numbers") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "for each=\"file_preview_line_rows\"") == null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"open_right_panel_file_edit\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-input=\"file_preview_edit\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"file_preview_save\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"file_preview_reload\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"file_preview_discard\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"file_preview_keep_editing\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "file_preview_discard_confirm") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "text=\"{file_preview_draft}\"") != null);

    main.update(&model, .open_right_panel_file_edit, &fx);
    try testing.expect(model.file_preview_editing());
    try testing.expect(!model.file_preview_dirty());
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Edit") == null);
    try testing.expect(findByText(tree.root, .button, "Save") == null);
    _ = try expectButtonMsg(tree, "Reload", .file_preview_reload);

    main.update(&model, .{ .file_preview_edit = .{ .insert_text = "// edited\n" } }, &fx);
    try testing.expect(model.file_preview_dirty());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Unsaved");
    _ = try expectButtonMsg(tree, "Save", .file_preview_save);

    main.update(&model, .file_preview_save, &fx);
    try testing.expect(!model.file_preview_editing());
    try testing.expect(!model.file_preview_dirty());
    try testing.expectEqualStrings("pub fn main() void {}\n// edited\n", model.file_preview_body());
    tree = try buildTree(arena, &model);
    _ = try expectButtonMsg(tree, "Edit", .open_right_panel_file_edit);
    try testing.expect(findByText(tree.root, .button, "Save") == null);
    try testing.expect(findByText(tree.root, .text, "Unsaved") == null);

    main.update(&model, .open_right_panel_file_editor, &fx);
    const spawn = findOpenEditorSpawn(&fx) orelse return error.MissingOpenEditorSpawn;
    try testing.expect(open_editor.isEditorArgv(spawn.argv));
    try testing.expect(std.mem.endsWith(u8, spawn.argv[1], "/src/main.zig"));
    try testing.expect(std.mem.startsWith(u8, spawn.argv[1], project));

    main.update(&model, .close_right_panel_file_preview, &fx);
    try testing.expect(!model.right_panel_file_preview_open());
    try testing.expectEqual(@as(usize, 0), model.right_panel_file_preview_storage.len);
    try testing.expectEqual(@as(usize, 0), model.file_preview_line_rows(arena).len);

    main.update(&model, .{ .toggle_right_panel_dir = file_mention.file_mention_dir_id_base }, &fx);
    try testing.expectEqual(@as(usize, 2), model.right_panel_file_rows(arena).len);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "main.zig") == null);
}

test "Files preview dirty Close shows discard confirm; Keep editing and Discard" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, "/tmp/faku-preview-discard-ui-{s}", .{tmp.sub_path});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);
    var a_buf: [300]u8 = undefined;
    const a_abs = try std.fmt.bufPrint(&a_buf, "{s}/a.txt", .{project});
    try std.Io.Dir.cwd().writeFile(testing.io, .{ .sub_path = a_abs, .data = "aaa\n" });
    var b_buf: [300]u8 = undefined;
    const b_abs = try std.fmt.bufPrint(&b_buf, "{s}/b.txt", .{project});
    try std.Io.Dir.cwd().writeFile(testing.io, .{ .sub_path = b_abs, .data = "bbb\n" });

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const first = model.addSession("discard ui", .fx);
    const second = model.addSession("other session", .fx);
    model.selected = first;
    model.setSelectedProjectPath(project);
    defer right_panel.clearFilePreview(&model);

    main.update(&model, .show_right_panel, &fx);
    file_mention.applyStdoutPaths(&model, "a.txt\nb.txt\n");
    main.update(&model, .{ .open_right_panel_file = 1 }, &fx);
    main.update(&model, .open_right_panel_file_edit, &fx);
    main.update(&model, .{ .file_preview_edit = .{ .insert_text = "x" } }, &fx);
    try testing.expect(model.file_preview_dirty());

    var tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Discard") == null);
    try testing.expect(findByText(tree.root, .text, "Discard unsaved changes?") == null);

    main.update(&model, .{ .open_right_panel_file = 2 }, &fx);
    try testing.expect(model.file_preview_discard_confirm());
    try testing.expectEqual(@as(u32, 1), model.right_panel_file_preview_id);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Discard unsaved changes?");
    _ = try expectButtonMsg(tree, "Discard", .file_preview_discard);
    _ = try expectButtonMsg(tree, "Keep editing", .file_preview_keep_editing);
    _ = try expectButtonMsg(tree, "Save", .file_preview_save);

    main.update(&model, .file_preview_keep_editing, &fx);
    try testing.expect(!model.file_preview_discard_confirm());
    try testing.expect(model.file_preview_dirty());
    try testing.expectEqual(@as(u32, 1), model.right_panel_file_preview_id);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Discard") == null);

    main.update(&model, .close_right_panel_file_preview, &fx);
    try testing.expect(model.right_panel_file_preview_open());
    try testing.expect(model.file_preview_discard_confirm());
    main.update(&model, .file_preview_keep_editing, &fx);

    main.update(&model, .hide_right_panel, &fx);
    try testing.expect(model.right_panel_open);
    try testing.expect(model.file_preview_discard_confirm());
    main.update(&model, .file_preview_keep_editing, &fx);

    main.update(&model, .toggle_right_panel, &fx);
    try testing.expect(model.right_panel_open);
    try testing.expect(model.file_preview_discard_confirm());
    main.update(&model, .file_preview_keep_editing, &fx);

    main.update(&model, .{ .select = second }, &fx);
    try testing.expectEqual(first, model.selected);
    try testing.expect(model.file_preview_discard_confirm());
    main.update(&model, .file_preview_keep_editing, &fx);
    try testing.expectEqual(first, model.selected);

    main.update(&model, .new_session, &fx);
    try testing.expectEqual(first, model.selected);
    try testing.expectEqual(@as(u32, 2), model.session_count);
    try testing.expect(model.file_preview_discard_confirm());
    main.update(&model, .file_preview_keep_editing, &fx);

    main.update(&model, .close_right_panel_file_preview, &fx);
    main.update(&model, .file_preview_discard, &fx);
    try testing.expect(!model.right_panel_file_preview_open());
    try testing.expect(!model.file_preview_dirty());
    try testing.expect(model.right_panel_open);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Discard") == null);
    try testing.expect(findByText(tree.root, .text, "Discard unsaved changes?") == null);
}

