test "cmd-c and ctrl-c copy the last non-empty turn via writeClipboard" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    const other = model.addSession("other session", .fx);
    const id = model.addSession("copy last", .fx);
    model.selected = id;
    _ = model.appendTurn(other, .assistant, "not this session");

    const cmd_c = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "c",
        .modifiers = .{ .super = true },
    };
    const ctrl_c = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "C",
        .modifiers = .{ .control = true },
    };
    const plain_c = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "c" };

    try testing.expectEqual(@as(?Msg, null), keys.onKey(plain_c));
    try testing.expectEqual(Msg.copy_last_turn, keys.onKey(cmd_c).?);
    try testing.expectEqual(Msg.copy_last_turn, keys.onKey(ctrl_c).?);

    try testing.expectEqual(@as(usize, 0), fx.pendingClipboardCount());
    main.update(&model, keys.onKey(cmd_c).?, &fx);
    try testing.expectEqual(@as(usize, 0), fx.pendingClipboardCount());
    try testing.expectEqual(@as(usize, 0), fx.pendingSpawnCount());

    _ = model.appendTurn(id, .user, "");
    _ = model.appendTurn(id, .assistant, "");
    main.update(&model, .copy_last_turn, &fx);
    try testing.expectEqual(@as(usize, 0), fx.pendingClipboardCount());

    _ = model.appendTurn(id, .user, "first visible");
    _ = model.appendTurn(id, .assistant, "last non-empty body");
    _ = model.appendTurn(id, .tool, "");
    const tree = try buildTree(arena, &model);
    _ = try expectButton(tree.root, "Copy");
    try testing.expect(findByText(tree.root, .button, "Rewind") == null);

    main.update(&model, keys.onKey(cmd_c).?, &fx);
    try testing.expectEqual(@as(usize, 1), fx.pendingClipboardCount());
    const first = fx.pendingClipboardAt(0).?;
    try testing.expectEqual(main.copy_turn_key, first.key);
    try testing.expectEqual(native_sdk.EffectClipboardOp.write, first.op);
    try testing.expectEqualStrings("last non-empty body", first.text);

    main.update(&model, keys.onKey(ctrl_c).?, &fx);
    try testing.expectEqual(@as(usize, 1), fx.pendingClipboardCount());
    try testing.expectEqual(main.copy_turn_key, fx.pendingClipboardAt(0).?.key);
    try testing.expectEqualStrings("last non-empty body", fx.pendingClipboardAt(0).?.text);

    const cmd_b = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "b",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.toggle_sidebar, keys.onKey(cmd_b).?);
    const cmd_back = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "[",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.history_back, keys.onKey(cmd_back).?);
    const cmd_forward = canvas.WidgetKeyboardEvent{
        .phase = .key_down,
        .key = "]",
        .modifiers = .{ .super = true },
    };
    try testing.expectEqual(Msg.history_forward, keys.onKey(cmd_forward).?);
}

fn expectLaidOutHeight(root: canvas.Widget, id: canvas.ObjectId, height: f32) !void {
    var nodes: [256]canvas.WidgetLayoutNode = undefined;
    const layout = try canvas.layoutWidgetTree(
        root,
        native_sdk.geometry.RectF.init(0, 0, main.window_width, main.window_height),
        &nodes,
    );
    for (layout.nodes) |node| {
        if (node.widget.id == id) {
            try testing.expectEqual(height, node.frame.height);
            return;
        }
    }
    return error.WidgetNotFound;
}

fn expectRowTitles(rows: []const main.SessionRow, expected: []const []const u8) !void {
    try testing.expectEqual(expected.len, rows.len);
    for (rows, expected) |row, title| {
        try testing.expectEqualStrings(title, row.title);
    }
}

fn expectSidebarTitles(rows: []const main.SidebarRow, expected: []const []const u8) !void {
    try testing.expectEqual(expected.len, rows.len);
    for (rows, expected) |row, title| {
        try testing.expectEqualStrings(title, row.title);
    }
}

fn paletteHasLabel(rows: []const main.PaletteRow, label: []const u8) bool {
    for (rows) |row| {
        if (std.mem.eql(u8, row.label, label)) return true;
    }
    return false;
}

fn paletteRowId(rows: []const main.PaletteRow, label: []const u8) u32 {
    for (rows) |row| {
        if (std.mem.eql(u8, row.label, label)) return row.id;
    }
    return 0;
}

fn paletteRowIsAction(rows: []const main.PaletteRow, label: []const u8) bool {
    for (rows) |row| {
        if (std.mem.eql(u8, row.label, label)) return row.is_action and !row.is_header and !row.is_session;
    }
    return false;
}

fn expectOneLineEllipsis(widget: canvas.Widget, grow: ?f32) !void {
    try testing.expect(widget.kind == .text);
    if (@hasField(canvas.Widget, "text_no_wrap")) {
        try testing.expect(widget.text_no_wrap);
    }
    if (@hasField(canvas.Widget, "text_overflow")) {
        try testing.expectEqual(canvas.TextOverflow.ellipsis, widget.text_overflow);
    }
    if (grow) |value| {
        try testing.expectEqual(value, widget.layout.grow);
    }
}

fn countByKind(widget: canvas.Widget, kind: canvas.WidgetKind) usize {
    var n: usize = if (widget.kind == kind) 1 else 0;
    for (widget.children) |child| n += countByKind(child, kind);
    return n;
}

fn sessionRowHasGroupRail(widget: canvas.Widget, title: []const u8) bool {
    var child_is_target = false;
    for (widget.children) |child| {
        if (child.kind == .list_item and std.mem.eql(u8, widgetName(child), title)) child_is_target = true;
        if (sessionRowHasGroupRail(child, title)) return true;
    }
    if (!child_is_target) return false;
    for (widget.children) |child| {
        if (child.kind == .separator) return true;
        // Native spacer is a stack leaf (ui_schema maps spacer → stack).
        if (child.kind == .stack) return true;
    }
    return false;
}

test "sidebar Search opens the command palette; title match stays in Tasks" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    try testing.expectEqual(@as(u32, 2), model.session_count);
    try testing.expectEqualStrings("", model.search_query());
    try testing.expect(!model.palette_open);

    var rows = model.session_rows(arena);
    try expectRowTitles(rows, &.{ "port waku to zig", "fix auth listener" });

    var tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Today");
    const search_btn = try expectButton(tree.root, "Search");
    try expectLaidOutHeight(tree.root, search_btn.id, 32);

    main.update(&model, tree.msgForPointer(search_btn.id, .up).?, &fx);
    try testing.expect(model.palette_open);
    try testing.expectEqualStrings("", model.search_query());
    rows = model.session_rows(arena);
    try expectRowTitles(rows, &.{ "port waku to zig", "fix auth listener" });
    try testing.expect(paletteHasLabel(model.palette_rows(arena), "New Task"));

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Today");
    _ = try expectButton(tree.root, "Search");
    _ = try expectButton(tree.root, "port waku to zig");
    _ = try expectButton(tree.root, "fix auth listener");
    const dialog = findByKind(tree.root, .dialog) orelse return error.WidgetNotFound;
    try testing.expectEqualStrings("Command palette", widgetName(dialog));
    if (findByKind(dialog, .search_field)) |field| {
        try testing.expectEqualStrings("Search", field.placeholder);
        try expectLaidOutHeight(tree.root, field.id, 60);
        try testing.expect(field.autofocus);
    } else return error.WidgetNotFound;
    _ = try expectButton(dialog, "New Task");

    main.update(&model, .{ .search_edit = .{ .insert_text = "WAKU" } }, &fx);
    try testing.expectEqualStrings("WAKU", model.search_query());
    try testing.expect(model.palette_open);
    rows = model.session_rows(arena);
    try expectRowTitles(rows, &.{ "port waku to zig", "fix auth listener" });
    try testing.expect(paletteHasLabel(model.palette_rows(arena), "port waku to zig"));
    try testing.expect(!paletteHasLabel(model.palette_rows(arena), "fix auth listener"));

    tree = try buildTree(arena, &model);
    _ = try expectButton(tree.root, "port waku to zig");
    _ = try expectButton(tree.root, "fix auth listener");
    _ = try expectByText(tree.root, .text, "Today");
    const palette = findByKind(tree.root, .dialog) orelse return error.WidgetNotFound;
    _ = try expectButton(palette, "port waku to zig");
    try testing.expect(findPressableContaining(palette, "fix auth listener") == null);

    main.update(&model, .{ .search_edit = .clear }, &fx);
    try testing.expectEqualStrings("", model.search_query());
    try testing.expect(model.palette_open);
    rows = model.session_rows(arena);
    try expectRowTitles(rows, &.{ "port waku to zig", "fix auth listener" });
    try testing.expect(paletteHasLabel(model.palette_rows(arena), "New Task"));

    main.update(&model, .{ .search_edit = .{ .insert_text = "auth" } }, &fx);
    try testing.expect(paletteHasLabel(model.palette_rows(arena), "fix auth listener"));
    try expectRowTitles(model.session_rows(arena), &.{ "port waku to zig", "fix auth listener" });

    tree = try buildTree(arena, &model);
    const palette_auth = try expectButton(
        findByKind(tree.root, .dialog) orelse return error.WidgetNotFound,
        "fix auth listener",
    );
    try testing.expectEqual(
        Msg{ .palette_pick = model.session_store[1].id },
        tree.msgForPointer(palette_auth.id, .up).?,
    );
    main.update(&model, tree.msgForPointer(palette_auth.id, .up).?, &fx);
    try testing.expectEqualStrings("fix auth listener", model.selected_title());
    try testing.expectEqualStrings("claude", model.selected_provider());
    try testing.expect(model.composer_active);
    try testing.expect(!model.palette_open);
    try testing.expectEqual(@as(usize, 1), countRole(&model, .user));
    try testing.expectEqual(@as(usize, 2), countRole(&model, .assistant));

    main.update(&model, .start_search, &fx);
    main.update(&model, .{ .search_edit = .{ .insert_text = "auth" } }, &fx);
    main.update(&model, .stop, &fx);
    try testing.expectEqualStrings("", model.search_query());
    try testing.expect(!model.palette_open);
    rows = model.session_rows(arena);
    try expectRowTitles(rows, &.{ "port waku to zig", "fix auth listener" });

    tree = try buildTree(arena, &model);
    _ = try expectButton(tree.root, "Search");
    _ = try expectButton(tree.root, "port waku to zig");
    _ = try expectButton(tree.root, "fix auth listener");
    try testing.expect(findByKind(tree.root, .dialog) == null);
}

