test "theme preference defaults to System; Light/Dark force scheme regardless of OS" {
    var model = Model{};
    try testing.expectEqual(main.ThemePreference.system, model.theme_preference);
    try testing.expect(model.theme_system());
    try testing.expectEqual(main.LanguagePreference.system, model.language_preference);
    try testing.expect(model.language_system());
    try testing.expectEqual(main.LanguagePreference.system, main.LanguagePreference.fromPersist(""));
    try testing.expectEqual(main.LanguagePreference.system, main.LanguagePreference.fromPersist("nope"));
    try testing.expectEqual(main.LanguagePreference.english, main.LanguagePreference.fromPersist("english"));
    try testing.expectEqual(main.ThemePreference.system, main.ThemePreference.fromPersist(""));
    try testing.expectEqual(main.ThemePreference.system, main.ThemePreference.fromPersist("nope"));
    try testing.expectEqual(main.ThemePreference.system, main.ThemePreference.fromPersist("system"));
    try testing.expectEqual(main.ThemePreference.light, main.ThemePreference.fromPersist("light"));
    try testing.expectEqual(main.ThemePreference.dark, main.ThemePreference.fromPersist("dark"));

    model.appearance = .{ .color_scheme = .dark };
    try testing.expectEqual(canvas.ColorScheme.dark, main.resolvedColorScheme(&model));
    const os_dark = main.designTokens(&model);
    try testing.expect(!os_dark.pixel_snap.geometry);

    model.appearance = .{ .color_scheme = .light };
    try testing.expectEqual(canvas.ColorScheme.light, main.resolvedColorScheme(&model));
    const os_light = main.designTokens(&model);
    try testing.expect(!std.meta.eql(os_dark.colors.background, os_light.colors.background));

    model.appearance = .{ .color_scheme = .dark };
    model.theme_preference = .light;
    try testing.expectEqual(canvas.ColorScheme.light, main.resolvedColorScheme(&model));
    const forced_light = main.designTokens(&model);
    try testing.expect(std.meta.eql(forced_light.colors.background, os_light.colors.background));
    try testing.expect(!forced_light.pixel_snap.geometry);

    model.appearance = .{ .color_scheme = .light };
    model.theme_preference = .dark;
    try testing.expectEqual(canvas.ColorScheme.dark, main.resolvedColorScheme(&model));
    const forced_dark = main.designTokens(&model);
    try testing.expect(std.meta.eql(forced_dark.colors.background, os_dark.colors.background));

    model.theme_preference = .light;
    model.appearance = .{ .color_scheme = .dark, .high_contrast = true, .reduce_motion = true };
    try testing.expectEqual(canvas.ColorScheme.light, main.resolvedColorScheme(&model));
    const forced_light_a11y = main.designTokens(&model);
    try testing.expect(!std.meta.eql(forced_light_a11y.colors.background, os_light.colors.background) or
        !std.meta.eql(forced_light_a11y.colors.text, os_light.colors.text));
    try testing.expectEqualStrings("High contrast on, reduce motion on. These follow the OS.", model.appearance_os_caption());
}

test "settings Skills lists SKILL.md name and path; select shows body" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-skills-ui", .{tmp.sub_path[0..]});
    var skill_dir_buf: [256]u8 = undefined;
    const skill_dir = try std.fmt.bufPrint(&skill_dir_buf, "{s}/.cursor/skills/demo", .{project});
    try std.Io.Dir.cwd().createDirPath(testing.io, skill_dir);
    var file_buf: [256]u8 = undefined;
    const file_path = try std.fmt.bufPrint(&file_buf, "{s}/SKILL.md", .{skill_dir});
    try std.Io.Dir.cwd().writeFile(testing.io, .{
        .sub_path = file_path,
        .data =
        \\---
        \\name: demo-skill
        \\---
        \\
        \\Use this skill.
        \\
        ,
    });

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("skills ui", .fx);
    model.selected = id;
    model.sessionById(id).?.setProjectPath(project);

    main.update(&model, .toggle_settings, &fx);
    main.update(&model, .set_settings_page_skills, &fx);
    try testing.expect(model.settings_page_skills());
    try testing.expect(model.skill_key >= main.skills_key_first);
    var i: usize = 0;
    var spawn = fx.pendingSpawnAt(0);
    while (spawn) |item| : (i += 1) {
        if (item.key == model.skill_key and skills.isSkillsWalkArgv(item.argv)) break;
        spawn = fx.pendingSpawnAt(i + 1);
    }
    try testing.expect(spawn != null);
    try testing.expect(skills.isSkillsWalkArgv(spawn.?.argv));
    try testing.expectEqualStrings(project, spawn.?.argv[4]);

    skills.applyStdoutPaths(&model, ".cursor/skills/demo/SKILL.md\n");
    try testing.expectEqual(@as(u32, 1), model.skill_count);
    try testing.expectEqualStrings("demo-skill", skills.cachedName(&model, 0));

    var tree = try buildTree(arena, &model);
    const row = try expectByText(tree.root, .list_item, "demo-skill");
    try testing.expectEqual(Msg{ .select_skill = 1 }, tree.msgForPointer(row.id, .up).?);
    _ = try expectByText(tree.root, .text, "demo-skill");
    _ = try expectByText(tree.root, .text, ".cursor/skills/demo/SKILL.md");
    try testing.expect(findByText(tree.root, .text, "Use this skill.") == null);

    main.update(&model, .{ .select_skill = 1 }, &fx);
    try testing.expectEqual(@as(u32, 1), model.skill_selected_id);
    try testing.expectEqualStrings("Use this skill.", model.skill_body());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Use this skill.");
}

