test "settings Providers Use for this session applies to selected session and persists" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-apply-provider", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    model.task_state_loaded = true;
    model.setStoreDir(dir);
    model.store_io = testing.io;
    try store.saveSession(&model, model.selected, testing.allocator, testing.io);
    try testing.expectEqual(main.Provider.fx, model.session_store[0].provider);
    try testing.expectEqual(main.Provider.claude, model.session_store[1].provider);

    main.update(&model, .toggle_settings, &fx);
    main.update(&model, .set_settings_page_providers, &fx);
    main.update(&model, .{ .select_provider = 2 }, &fx);
    try testing.expectEqual(main.Provider.fx, model.session_store[0].provider);

    var tree = try buildTree(arena, &model);
    const apply = try expectButtonMsg(tree, providers.apply_session_label, .apply_session_provider);
    main.update(&model, tree.msgForPointer(apply.id, .up).?, &fx);
    try testing.expectEqual(main.Provider.claude, model.session_store[0].provider);
    try testing.expectEqualStrings("claude", model.selected_provider());
    try testing.expectEqual(main.Provider.claude, model.session_store[1].provider);

    var loaded = Model{};
    loaded.setStoreDir(dir);
    loaded.store_io = testing.io;
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, testing.allocator, testing.io));
    try testing.expectEqual(main.Provider.claude, loaded.session_store[0].provider);
    try testing.expectEqualStrings("claude", loaded.selected_provider());

    main.update(&model, .{ .select_provider = 1 }, &fx);
    main.update(&model, .apply_session_provider, &fx);
    try testing.expectEqual(main.Provider.fx, model.session_store[0].provider);
    try testing.expectEqualStrings("fx", model.selected_provider());

    loaded = Model{};
    loaded.setStoreDir(dir);
    loaded.store_io = testing.io;
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, testing.allocator, testing.io));
    try testing.expectEqual(main.Provider.fx, loaded.session_store[0].provider);

    const previous = model.session_store[0].provider;
    model.provider_selected_id = 99;
    try testing.expect(!model.can_apply_session_provider());
    main.update(&model, .apply_session_provider, &fx);
    try testing.expectEqual(previous, model.session_store[0].provider);

    model.provider_selected_id = 2;
    model.selected = 0;
    try testing.expect(!model.can_apply_session_provider());
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, providers.apply_session_label) == null);
    main.update(&model, .apply_session_provider, &fx);
    try testing.expectEqual(main.Provider.fx, model.session_store[0].provider);
    try testing.expectEqual(main.Provider.claude, model.session_store[1].provider);
}

test "settings Providers fx copy install when missing, copy login when available; other missing is PATH hint" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    try testing.expect(!model.fx_available);
    main.update(&model, .toggle_settings, &fx);
    main.update(&model, .set_settings_page_providers, &fx);
    const probes_after_open = fx.pendingSpawnCount();

    main.update(&model, .{ .select_provider = 1 }, &fx);
    try testing.expect(model.can_copy_fx_install());
    try testing.expect(!model.can_copy_fx_login());
    try testing.expect(!model.has_other_install_hint());
    try testing.expect(model.can_apply_session_provider());

    var tree = try buildTree(arena, &model);
    _ = try expectButtonMsg(tree, providers.copy_install_label, .copy_fx_install);
    try testing.expect(findByText(tree.root, .button, providers.copy_login_label) == null);
    try testing.expect(findTextContaining(tree.root, providers.fx_install_command) != null);
    try testing.expect(findTextContaining(tree.root, providers.other_install_hint) == null);
    _ = try expectButtonMsg(tree, providers.apply_session_label, .apply_session_provider);

    const install = try expectButtonMsg(tree, providers.copy_install_label, .copy_fx_install);
    try testing.expectEqual(@as(usize, 0), fx.pendingClipboardCount());
    main.update(&model, tree.msgForPointer(install.id, .up).?, &fx);
    try testing.expectEqual(@as(usize, 1), fx.pendingClipboardCount());
    try testing.expectEqual(probes_after_open, fx.pendingSpawnCount());
    const written_install = fx.pendingClipboardAt(0).?;
    try testing.expectEqual(main.copy_turn_key, written_install.key);
    try testing.expectEqual(native_sdk.EffectClipboardOp.write, written_install.op);
    try testing.expectEqualStrings("curl -fsSL https://github.com/keejkrej/fx/releases/latest/download/install | bash", written_install.text);
    try testing.expectEqualStrings(providers.fx_install_command, written_install.text);

    model.fx_available = true;
    model.setFxPath("/tmp/faku-fx-login");
    try testing.expect(!model.can_copy_fx_install());
    try testing.expect(model.can_copy_fx_login());
    tree = try buildTree(arena, &model);
    _ = try expectButtonMsg(tree, providers.copy_login_label, .copy_fx_login);
    try testing.expect(findByText(tree.root, .button, providers.copy_install_label) == null);
    try testing.expect(findTextContaining(tree.root, providers.fx_login_command) != null);
    try testing.expect(findTextContaining(tree.root, providers.fx_login_note) != null);
    try testing.expect(findTextContaining(tree.root, providers.fx_login_codex_note) != null);
    try testing.expect(findTextContaining(tree.root, providers.fx_install_command) == null);
    _ = try expectButtonMsg(tree, providers.apply_session_label, .apply_session_provider);

    var login_fx = Effects.init(testing.allocator);
    defer login_fx.deinit();
    login_fx.executor = .fake;
    const login = try expectButtonMsg(tree, providers.copy_login_label, .copy_fx_login);
    main.update(&model, tree.msgForPointer(login.id, .up).?, &login_fx);
    try testing.expectEqual(@as(usize, 1), login_fx.pendingClipboardCount());
    try testing.expectEqual(@as(usize, 0), login_fx.pendingSpawnCount());
    const written_login = login_fx.pendingClipboardAt(0).?;
    try testing.expectEqual(main.copy_turn_key, written_login.key);
    try testing.expectEqual(native_sdk.EffectClipboardOp.write, written_login.op);
    try testing.expectEqualStrings("fx login", written_login.text);
    try testing.expectEqualStrings(providers.fx_login_command, written_login.text);

    main.update(&model, .{ .select_provider = providers.rowId(.codex) }, &fx);
    try testing.expect(!model.can_copy_fx_install());
    try testing.expect(!model.can_copy_fx_login());
    try testing.expect(model.has_other_install_hint());
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, providers.copy_install_label) == null);
    try testing.expect(findByText(tree.root, .button, providers.copy_login_label) == null);
    try testing.expect(findTextContaining(tree.root, providers.other_install_hint) != null);
    try testing.expect(findTextContaining(tree.root, providers.fx_install_command) == null);
    _ = try expectButtonMsg(tree, providers.apply_session_label, .apply_session_provider);
}

test "settings edits persist model access and daemon address and reload" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-settings", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = main.initialModel();
    model.task_state_loaded = true;
    model.setStoreDir(dir);
    model.store_io = testing.io;
    try store.saveSession(&model, model.selected, testing.allocator, testing.io);

    var tree = try buildTree(arena, &model);
    const gear = try expectButton(tree.root, "Settings");
    main.update(&model, tree.msgForPointer(gear.id, .up).?, &fx);
    try testing.expect(model.settings_open);

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Default model");
    main.update(&model, .{ .settings_model_edit = .{ .insert_text = "openai/gpt-5.4" } }, &fx);
    try testing.expectEqualStrings("openai/gpt-5.4", model.lastModel());
    try testing.expectEqualStrings("openai/gpt-5.4", model.settings_model());

    const auto = try expectButton(tree.root, "Auto");
    main.update(&model, tree.msgForPointer(auto.id, .up).?, &fx);
    try testing.expectEqualStrings("auto", model.lastAccessMode());
    try testing.expect(model.access_auto());
    try testing.expect(!model.access_ask());
    try testing.expect(!model.access_full());

    main.update(&model, .{ .settings_project_edit = .{ .insert_text = "/tmp/faku-settings" } }, &fx);
    try testing.expectEqualStrings("/tmp/faku-settings", model.lastProjectPath());

    main.update(&model, .{ .settings_daemon_edit = .{ .insert_text = "127.0.0.1:8787" } }, &fx);
    try testing.expectEqualStrings("127.0.0.1:8787", model.lastDaemonAddress());
    try testing.expectEqual(@as(usize, 0), model.daemonAddress().len);

    var loaded = Model{};
    loaded.setStoreDir(dir);
    loaded.store_io = testing.io;
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, testing.allocator, testing.io));
    try testing.expectEqualStrings("openai/gpt-5.4", loaded.lastModel());
    try testing.expectEqualStrings("auto", loaded.lastAccessMode());
    try testing.expectEqualStrings("/tmp/faku-settings", loaded.lastProjectPath());
    try testing.expectEqualStrings("127.0.0.1:8787", loaded.lastDaemonAddress());
    try testing.expectEqual(@as(usize, 0), loaded.daemonAddress().len);

    const inherited = loaded.addSession("untitled next", .fx);
    try testing.expectEqualStrings("openai/gpt-5.4", loaded.sessionById(inherited).?.model());
    try testing.expectEqualStrings("auto", loaded.sessionById(inherited).?.accessMode());
    try testing.expectEqualStrings("/tmp/faku-settings", loaded.sessionById(inherited).?.projectPath());

    loaded.openSettings();
    main.update(&loaded, .{ .settings_daemon_edit = .clear }, &fx);
    try testing.expectEqual(@as(usize, 0), loaded.lastDaemonAddress().len);

    var cleared = Model{};
    cleared.setStoreDir(dir);
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&cleared, testing.allocator, testing.io));
    try testing.expectEqual(@as(usize, 0), cleared.lastDaemonAddress().len);
    try testing.expectEqualStrings("openai/gpt-5.4", cleared.lastModel());
    try testing.expectEqualStrings("auto", cleared.lastAccessMode());
}

