    try testing.expect(!git_checkout.isGitPushForceArgv(spawn.argv));
    try testing.expectEqual(@as(usize, 7), spawn.argv.len);
    try testing.expectEqualStrings(git_checkout.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_checkout.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(git_checkout.git_push_cmd, spawn.argv[6]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_checkout.git_push_cmd) == null);
    try testing.expect(spawn.key >= main.git_push_key_first);
    try testing.expect(spawn.key < main.git_worktree_add_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
    try testing.expect(spawn.key != main.git_numstat_key_first);
    try testing.expect(spawn.key != main.git_fetch_key_first);
    try testing.expect(spawn.key != main.git_delete_key_first);
    try testing.expect(spawn.key != main.git_dirty_key_first);
    try testing.expect(spawn.key != main.git_create_key_first);
    try testing.expect(spawn.key != main.git_checkout_key_first);
    try testing.expect(spawn.key != main.git_branch_list_key_first);
    try testing.expect(!git_branch.isGitBranchArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitCheckoutArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitTrackCheckoutArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitCreateArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitDeleteArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitFetchArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitBranchListArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitSetUpstreamPushArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitUpstreamArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitRemoteArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitWorktreeAddArgv(spawn.argv));
}

fn expectGitUpstreamArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(git_checkout.isGitUpstreamArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitPushArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitSetUpstreamPushArgv(spawn.argv));
    try testing.expectEqual(@as(usize, 10), spawn.argv.len);
    try testing.expectEqualStrings(git_checkout.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_checkout.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(git_checkout.git_rev_parse_cmd, spawn.argv[6]);
    try testing.expectEqualStrings(git_checkout.git_abbrev_ref, spawn.argv[7]);
    try testing.expectEqualStrings(git_checkout.git_symbolic_full_name, spawn.argv[8]);
    try testing.expectEqualStrings(git_checkout.git_upstream_rev, spawn.argv[9]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_checkout.git_upstream_rev) == null);
    try testing.expect(spawn.key >= main.git_push_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
}

fn expectGitRemoteArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(git_checkout.isGitRemoteArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitPushArgv(spawn.argv));
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_checkout.git_remote_cmd, spawn.argv[6]);
    try testing.expect(spawn.key >= main.git_push_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
}

fn expectGitSetUpstreamPushArgv(spawn: anytype, cwd: []const u8, remote: []const u8, branch: []const u8) !void {
    try testing.expect(git_checkout.isGitSetUpstreamPushArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitSetUpstreamPushForceArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitPushArgv(spawn.argv));
    try testing.expectEqual(@as(usize, 10), spawn.argv.len);
    try testing.expectEqualStrings(git_checkout.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_checkout.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(git_checkout.git_push_cmd, spawn.argv[6]);
    try testing.expectEqualStrings(git_checkout.git_set_upstream_flag, spawn.argv[7]);
    try testing.expectEqualStrings(remote, spawn.argv[8]);
    try testing.expectEqualStrings(branch, spawn.argv[9]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_checkout.git_set_upstream_flag) == null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], remote) == null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], branch) == null);
    try testing.expect(spawn.key >= main.git_push_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
}

fn feedUpstreamPresent(model: *Model, fx: *Effects, cwd: []const u8) !@TypeOf(fx.pendingSpawnAt(0).?) {
    const probe = findGitUpstreamSpawnKey(fx, model.git_push_key) orelse return error.MissingGitUpstreamSpawn;
    try expectGitUpstreamArgv(probe, cwd);
    try testing.expect(findGitPushSpawnKey(fx, probe.key) == null);
    try fx.feedLine(probe.key, "origin/main\n");
    drainEffects(model, fx);
    try fx.feedExit(probe.key, 0);
    drainEffects(model, fx);
    return findGitPushSpawnKey(fx, model.git_push_key) orelse return error.MissingGitPushSpawn;
}

test "Push menu item one-shots git push; success refreshes; failure sets status" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-push", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("push remotes", .fx);
    const other = model.addSession("other push", .fx);
    model.selected = id;

    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try fx.feedLine(branch.key, "main\n");
    drainEffects(&model, &fx);
    const list = findGitBranchListSpawnKey(&fx, model.git_branch_list_key) orelse return error.MissingGitBranchListSpawn;
    try fx.feedLine(list.key, "refs/heads/main\n");
    drainEffects(&model, &fx);
    try fx.feedExit(list.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.can_pick_git_branch());
    try finishAheadBehindNoUpstream(&fx, &model);

    main.update(&model, .toggle_git_branch_picker, &fx);
    try testing.expect(model.git_branch_picker_open);
    var tree = try buildTree(arena, &model);
    const push_item = try expectByText(tree.root, .menu_item, "Push…");
    try testing.expectEqual(Msg.start_git_push, tree.msgForPointer(push_item.id, .up).?);
    _ = try expectByText(tree.root, .menu_item, "Fetch…");

    model.phase = .streaming;
    main.update(&model, tree.msgForPointer(push_item.id, .up).?, &fx);
    try testing.expect(!model.git_branch_picker_open);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(!model.git_push_confirm_active);
    model.phase = .idle;

    main.update(&model, .toggle_git_branch_picker, &fx);
    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    try testing.expect(!model.git_push_force);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(!model.git_branch_picker_open);
    tree = try buildTree(arena, &model);
    const force_off = try expectButtonMsg(tree, "Force", .toggle_git_push_force);
    try testing.expect(!force_off.state.selected);
    _ = try expectButtonMsg(tree, "Push", .confirm_git_push);
    _ = try expectButtonMsg(tree, "Cancel", .cancel_git_push);
    main.update(&model, tree.msgForPointer(force_off.id, .up).?, &fx);
    try testing.expect(model.git_push_force);
    tree = try buildTree(arena, &model);
    const force_on = try expectButtonMsg(tree, "Force", .toggle_git_push_force);
    try testing.expect(force_on.state.selected);
    main.update(&model, tree.msgForPointer(force_on.id, .up).?, &fx);
    try testing.expect(!model.git_push_force);
    main.update(&model, .confirm_git_push, &fx);
    const pushed = try feedUpstreamPresent(&model, &fx, project);
    try expectGitPushArgv(pushed, project);
    try testing.expect(!model.git_branch_picker_open);
    try testing.expectEqualStrings("main", model.git_branch_label());

    const push_key = model.git_push_key;
    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(push_key, model.git_push_key);
    main.update(&model, .start_git_fetch, &fx);
    try testing.expectEqual(push_key, model.git_push_key);
    try testing.expectEqual(@as(u64, 0), model.git_fetch_key);
    main.update(&model, .{ .pick_git_branch = "main" }, &fx);
    try testing.expectEqual(push_key, model.git_push_key);
    try testing.expectEqual(@as(u64, 0), model.git_checkout_key);

    try fx.feedExit(pushed.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    const refreshed = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchRefresh;
    try testing.expect(findGitDirtySpawnKey(&fx, model.git_dirty_key) != null);
    try testing.expect(findGitNumstatSpawnKey(&fx, model.git_numstat_key) != null);
    try testing.expect(findFileMentionSpawnKey(&fx, model.file_mention_key) != null);
    try testing.expect(findGitBranchListSpawnKey(&fx, model.git_branch_list_key) != null);
    try testing.expectEqualStrings("", model.git_branch_label());
    try fx.feedLine(refreshed.key, "main\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("main", model.git_branch_label());
    try finishAheadBehindNoUpstream(&fx, &model);

    main.update(&model, .start_git_fetch, &fx);
    const fetch_in_flight = findGitFetchSpawnKey(&fx, model.git_fetch_key) orelse return error.MissingGitFetchInFlight;
    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(!model.git_push_confirm_active);
    try testing.expectEqual(fetch_in_flight.key, model.git_fetch_key);
    try fx.feedExit(fetch_in_flight.key, 1);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_fetch_key);
    model.clearAttachStatus();

    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const failed = try feedUpstreamPresent(&model, &fx, project);
    try expectGitPushArgv(failed, project);
    try fx.feedExit(failed.key, 1);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("main", model.git_branch_label());
    try testing.expectEqualStrings(git_checkout.push_failed_status, model.attach_status());
    try testing.expect(model.has_attach_status());
    try testing.expectEqual(@as(u64, 0), model.git_push_key);

    model.clearAttachStatus();
    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const cancel_spawn = try feedUpstreamPresent(&model, &fx, project);
    const cancel_key = cancel_spawn.key;
    try expectGitPushArgv(cancel_spawn, project);
    main.update(&model, .{ .select = other }, &fx);
    try testing.expectEqual(other, model.selected);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expectError(error.EffectNotFound, fx.feedExit(cancel_key, 0));
}

test "Push without upstream set-upstreams origin; detached and no remotes are no-ops" {
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-push-u", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("push no upstream", .fx);
    model.selected = id;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try fx.feedLine(branch.key, "feat/new\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("feat/new", model.git_branch_label());
    try finishAheadBehindNoUpstream(&fx, &model);

    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const upstream = findGitUpstreamSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitUpstreamSpawn;
    try expectGitUpstreamArgv(upstream, project);
    try testing.expect(findGitPushSpawnKey(&fx, upstream.key) == null);
    try fx.feedExit(upstream.key, 128);
    drainEffects(&model, &fx);
    try testing.expect(findGitPushShowCurrentSpawnKey(&fx, model.git_push_key) == null);
    const remotes = findGitRemoteSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitRemoteSpawn;
    try expectGitRemoteArgv(remotes, project);
    try fx.feedLine(remotes.key, "upstream\norigin\n");
    drainEffects(&model, &fx);
    try fx.feedExit(remotes.key, 0);
    drainEffects(&model, &fx);
    const set_up = findGitSetUpstreamPushSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitSetUpstreamPushSpawn;
    try expectGitSetUpstreamPushArgv(set_up, project, "origin", "feat/new");
    try testing.expect(findGitPushSpawnKey(&fx, set_up.key) == null);

    try fx.feedExit(set_up.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(findGitBranchSpawnKey(&fx, model.git_branch_key) != null);
    try testing.expect(findGitDirtySpawnKey(&fx, model.git_dirty_key) != null);
    try testing.expect(findGitNumstatSpawnKey(&fx, model.git_numstat_key) != null);
    try testing.expect(findFileMentionSpawnKey(&fx, model.file_mention_key) != null);
    try testing.expect(findGitBranchListSpawnKey(&fx, model.git_branch_list_key) != null);

    const refresh = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchRefresh;
    try fx.feedLine(refresh.key, "feat/new\n");
    drainEffects(&model, &fx);
    try finishAheadBehindNoUpstream(&fx, &model);

    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const no_remote_up = findGitUpstreamSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitNoRemoteUpstream;
    try fx.feedExit(no_remote_up.key, 1);
    drainEffects(&model, &fx);
    const empty_remotes = findGitRemoteSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitEmptyRemotes;
    try fx.feedExit(empty_remotes.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expectEqualStrings(git_checkout.push_failed_status, model.attach_status());
    try testing.expect(findGitPushSpawnKey(&fx, model.git_push_key) == null);
    try testing.expect(findGitSetUpstreamPushSpawnKey(&fx, model.git_push_key) == null);

    model.clearAttachStatus();
    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const detached_branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitDetachedBranch;
    try fx.feedExit(detached_branch.key, 0);
    drainEffects(&model, &fx);
    const sha = findGitRevParseSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitDetachedSha;
    try fx.feedLine(sha.key, "a1b2c3d\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("a1b2c3d", model.git_branch_label());
    try finishAheadBehindNoUpstream(&fx, &model);

    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const detached_up = findGitUpstreamSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitDetachedUpstream;
    try fx.feedExit(detached_up.key, 128);
    drainEffects(&model, &fx);
    const show = findGitPushShowCurrentSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitPushShowCurrent;
    try testing.expect(git_branch.isGitBranchArgv(show.argv));
    try testing.expectEqualStrings(project, show.argv[4]);
    try testing.expect(show.key >= main.git_push_key_first);
    try testing.expect(show.key < main.file_mention_key_first);
    try fx.feedExit(show.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expectEqualStrings(git_checkout.push_failed_status, model.attach_status());
    try testing.expect(findGitPushSpawnKey(&fx, model.git_push_key) == null);
    try testing.expect(findGitRemoteSpawnKey(&fx, model.git_push_key) == null);
    try testing.expect(findGitSetUpstreamPushSpawnKey(&fx, model.git_push_key) == null);

    model.clearAttachStatus();
    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    const show_up = findGitUpstreamSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitShowCurrentUpstream;
    try fx.feedExit(show_up.key, 128);
    drainEffects(&model, &fx);
    const show_ok = findGitPushShowCurrentSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitPushShowCurrentOk;
    try fx.feedLine(show_ok.key, "hotfix\n");
    drainEffects(&model, &fx);
    try fx.feedExit(show_ok.key, 0);
    drainEffects(&model, &fx);
    const github = findGitRemoteSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitGithubRemote;
    try fx.feedLine(github.key, "github\n");
    drainEffects(&model, &fx);
    try fx.feedExit(github.key, 0);
    drainEffects(&model, &fx);
    const set_github = findGitSetUpstreamPushSpawnKey(&fx, model.git_push_key) orelse return error.MissingGitSetUpstreamGithub;
    try expectGitSetUpstreamPushArgv(set_github, project, "github", "hotfix");
    try testing.expect(!git_checkout.isGitPushArgv(set_github.argv));
}

fn findGitWorktreeAddSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and git_checkout.isGitWorktreeAddArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn findGitWorktreeBaseSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and git_checkout.isGitWorktreeBaseArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn expectGitWorktreeBaseArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(git_checkout.isGitWorktreeBaseArgv(spawn.argv));
    try testing.expectEqual(@as(usize, 10), spawn.argv.len);
    try testing.expectEqualStrings(git_checkout.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_checkout.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(git_checkout.git_symbolic_ref_cmd, spawn.argv[6]);
    try testing.expectEqualStrings(git_checkout.git_quiet_flag, spawn.argv[7]);
    try testing.expectEqualStrings(git_checkout.git_short_flag, spawn.argv[8]);
    try testing.expectEqualStrings(git_checkout.git_origin_head_ref, spawn.argv[9]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_checkout.git_origin_head_ref) == null);
    try testing.expect(spawn.key >= main.git_worktree_base_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
    try testing.expect(spawn.key > main.git_ahead_behind_key_first);
    try testing.expect(!git_checkout.isGitWorktreeAddArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitUpstreamArgv(spawn.argv));
}

fn finishWorktreeBaseProbe(fx: *Effects, model: *Model, stdout: []const u8, code: u8) !void {
    const probe = findGitWorktreeBaseSpawnKey(fx, model.git_worktree_base_key) orelse return error.MissingGitWorktreeBaseSpawn;
    try expectGitWorktreeBaseArgv(probe, model.selectedProjectPath());
    if (stdout.len > 0) try fx.feedLine(probe.key, stdout);
    drainEffects(model, fx);
    try fx.feedExit(probe.key, code);
    drainEffects(model, fx);
}

fn failWorktreeAddFirstThenExhaust(fx: *Effects, model: *Model, cwd: []const u8, home: []const u8, slug: []const u8, base: []const u8) !void {
    const first = findGitWorktreeAddSpawnKey(fx, model.git_worktree_add_key) orelse return error.MissingGitWorktreeAddFailSpawn;
    try expectGitWorktreeAddArgv(first, cwd, home, slug, base);
    try testing.expectEqualStrings(cwd, model.selectedProjectPath());
    try fx.feedExit(first.key, 1);
    drainEffects(model, fx);
    try testing.expect(!model.has_attach_status());
    try testing.expect(model.git_worktree_create_active);
    try testing.expectEqualStrings(cwd, model.selectedProjectPath());

    var name_buf: [git_branch.max_git_branch]u8 = undefined;
    const retry_name = git_checkout.worktreeCandidateName(slug, 1, name_buf[0..]) orelse return error.MissingWorktreeRetryName;
    const retry = findGitWorktreeAddSpawnKey(fx, model.git_worktree_add_key) orelse return error.MissingGitWorktreeAddRetry;
    try expectGitWorktreeAddArgv(retry, cwd, home, retry_name, base);
    model.git_worktree_add_attempt = git_checkout.max_worktree_candidates - 1;
    try fx.feedExit(retry.key, 1);
    drainEffects(model, fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expectEqualStrings(cwd, model.selectedProjectPath());
    try testing.expectEqualStrings(git_checkout.worktree_add_failed_status, model.attach_status());
    try testing.expect(model.has_attach_status());
    try testing.expect(model.git_worktree_create_active);
}

fn expectGitWorktreeAddArgv(spawn: anytype, cwd: []const u8, home: []const u8, name: []const u8, base: []const u8) !void {
    var parent_buf: [main.max_project_path]u8 = undefined;
    const parent = git_checkout.worktreeParentPath(home, cwd, parent_buf[0..]) orelse return error.MissingWorktreeParent;
    var dest_buf: [main.max_project_path]u8 = undefined;
    const dest = git_checkout.worktreeDestPath(home, cwd, name, dest_buf[0..]) orelse return error.MissingWorktreeDest;
    var branch_buf: [git_branch.max_git_branch]u8 = undefined;
    const branch = git_checkout.worktreeBranchName(name, branch_buf[0..]) orelse return error.MissingWorktreeBranch;
    try testing.expect(git_checkout.isGitWorktreeAddArgv(spawn.argv));
    if (base.len == 0) {
        try testing.expectEqual(@as(usize, 12), spawn.argv.len);
    } else {
        try testing.expectEqual(@as(usize, 13), spawn.argv.len);
        try testing.expectEqualStrings(base, spawn.argv[12]);
        try testing.expect(std.mem.indexOf(u8, spawn.argv[2], base) == null);
    }
    try testing.expectEqualStrings(git_checkout.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(git_checkout.git_worktree_mkdir_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(parent, spawn.argv[4]);
    try testing.expectEqualStrings(cwd, spawn.argv[5]);
    try testing.expectEqualStrings(git_checkout.git_bin, spawn.argv[6]);
    try testing.expectEqualStrings(git_checkout.git_worktree_cmd, spawn.argv[7]);
    try testing.expectEqualStrings(git_checkout.git_worktree_add_cmd, spawn.argv[8]);
    try testing.expectEqualStrings(git_checkout.git_create_b_flag, spawn.argv[9]);
    try testing.expectEqualStrings(branch, spawn.argv[10]);
    try testing.expectEqualStrings(dest, spawn.argv[11]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], name) == null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], dest) == null);
    try testing.expect(spawn.key >= main.git_worktree_add_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
    try testing.expect(spawn.key != main.git_push_key_first);
    try testing.expect(!git_checkout.isGitCreateArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitPushArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitCheckoutArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitWorktreeBaseArgv(spawn.argv));
}

test "New worktree opens create UI; Esc and cancel close it" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-wt-ui", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("worktree ui", .fx);
    model.selected = id;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try fx.feedLine(branch.key, "main\n");
    drainEffects(&model, &fx);
    const list = findGitBranchListSpawnKey(&fx, model.git_branch_list_key) orelse return error.MissingGitBranchListSpawn;
    try fx.feedLine(list.key, "refs/heads/main\n");
    drainEffects(&model, &fx);
    try fx.feedLine(list.key, "refs/heads/feat/old\n");
    drainEffects(&model, &fx);
    try fx.feedExit(list.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.can_pick_git_branch());

    main.update(&model, .toggle_git_branch_picker, &fx);
    try testing.expect(model.git_branch_picker_open);
    var tree = try buildTree(arena, &model);
    const new_item = try expectByText(tree.root, .menu_item, "New worktree…");
    try testing.expectEqual(Msg.start_git_worktree_create, tree.msgForPointer(new_item.id, .up).?);
    _ = try expectByText(tree.root, .menu_item, "New branch…");
    try testing.expect(findByPlaceholder(tree.root, .text_field, "New worktree name") == null);

    main.update(&model, tree.msgForPointer(new_item.id, .up).?, &fx);
    try testing.expect(!model.git_branch_picker_open);
    try testing.expect(model.git_worktree_create_active);
    try testing.expect(!model.git_branch_create_active);
    try testing.expectEqualStrings("worktree-ui", model.git_worktree_create());
    try testing.expectEqualStrings("main", model.git_worktree_base_label());
    try testing.expect(!model.git_worktree_base_picker_open);
    tree = try buildTree(arena, &model);
    try testing.expect(findByKind(tree.root, .dropdown_menu) == null);
    try testing.expect(findByPlaceholder(tree.root, .text_field, "New worktree name") != null);
    _ = try expectByText(tree.root, .text, "main");
    _ = try expectButtonMsg(tree, "Base", .toggle_git_worktree_base_picker);
    _ = try expectButtonMsg(tree, "Create", .confirm_git_worktree_create);
    _ = try expectButtonMsg(tree, "Cancel", .cancel_git_worktree_create);

    main.update(&model, .toggle_git_worktree_base_picker, &fx);
    try testing.expect(model.git_worktree_base_picker_open);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .menu_item, "feat/old");
    _ = try expectByText(tree.root, .menu_item, "main");

    const escape = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "escape" };
    try testing.expectEqual(Msg.stop, keys.onKey(escape).?);
    main.update(&model, keys.onKey(escape).?, &fx);
    try testing.expect(!model.git_worktree_base_picker_open);
    try testing.expect(model.git_worktree_create_active);

    main.update(&model, .toggle_git_worktree_base_picker, &fx);
    main.update(&model, .{ .pick_git_worktree_base = "feat/old" }, &fx);
    try testing.expect(!model.git_worktree_base_picker_open);
    try testing.expectEqualStrings("feat/old", model.git_worktree_base_label());

    main.update(&model, keys.onKey(escape).?, &fx);
    try testing.expect(!model.git_worktree_create_active);
    try testing.expectEqual(@as(usize, 0), model.git_worktree_base_override_len);
    tree = try buildTree(arena, &model);
    try testing.expect(findByPlaceholder(tree.root, .text_field, "New worktree name") == null);

    main.update(&model, .toggle_git_branch_picker, &fx);
    main.update(&model, .start_git_worktree_create, &fx);
    try testing.expectEqualStrings("worktree-ui", model.git_worktree_create());
    try testing.expectEqualStrings("main", model.git_worktree_base_label());
    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat-tmp" } }, &fx);
    try testing.expectEqualStrings("feat-tmp", model.git_worktree_create());
    main.update(&model, .{ .pick_git_worktree_base = "feat/old" }, &fx);
    try testing.expectEqualStrings("feat/old", model.git_worktree_base_label());
    main.update(&model, .cancel_git_worktree_create, &fx);
    try testing.expect(!model.git_worktree_create_active);
    try testing.expectEqualStrings("", model.git_worktree_create());
    try testing.expectEqual(@as(usize, 0), model.git_worktree_base_override_len);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
}

test "Commit menu item opens a message card before Push; empty confirm does not spawn" {
