    try testing.expect(!model.has_git_commit_committing_and_pushing());
    try testing.expect(!model.has_git_commit_push_only());
    try testing.expect(!model.has_git_commit_generate());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Committing…");
    try testing.expect(findByText(tree.root, .text, "Generating…") == null);
    try testing.expect(findByText(tree.root, .text, "Amending…") == null);
    try testing.expect(findByText(tree.root, .text, "Committing and pushing…") == null);
    try testing.expect(findByText(tree.root, .text, "Pushing…") == null);

    main.update(&model, .cancel_git_commit, &fx);
    try testing.expect(!model.git_commit_active);
    try testing.expect(!model.has_git_commit_committing());

    main.update(&model, .start_git_commit, &fx);
    main.update(&model, .{ .git_commit_edit = .{ .insert_text = "ship the dirty probe" } }, &fx);
    main.update(&model, .confirm_git_commit_and_push, &fx);
    try testing.expect(model.git_commit_then_push);
    try testing.expect(model.has_git_commit_committing_and_pushing());
    try testing.expect(!model.has_git_commit_committing());
    try testing.expect(!model.has_git_commit_push_only());
    try testing.expect(!model.has_git_commit_pushing());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Committing and pushing…");
    try testing.expect(findByText(tree.root, .text, "Committing…") == null);
    try testing.expect(findByText(tree.root, .text, "Amending…") == null);
    try testing.expect(findByText(tree.root, .text, "Pushing…") == null);
    try testing.expect(findByText(tree.root, .text, "Generating…") == null);

    const add = findPendingGitCommitAdd(&fx, model.git_commit_key) orelse return error.MissingGitAddSpawn;
    git_commit.handleCommitExit(&model, &fx, .{ .key = add.key, .reason = .exited, .code = 0 });
    try testing.expect(model.has_git_commit_committing_and_pushing());
    const preflight = findPendingGitCommitCachedQuiet(&fx, model.git_commit_key) orelse return error.MissingGitCachedQuietSpawn;
    git_commit.handleCommitExit(&model, &fx, .{ .key = preflight.key, .reason = .exited, .code = 1 });
    try testing.expect(model.has_git_commit_committing_and_pushing());
    const commit = findPendingGitCommitCmd(&fx, model.git_commit_key) orelse return error.MissingGitCommitSpawn;
    git_commit.handleCommitExit(&model, &fx, .{ .key = commit.key, .reason = .exited, .code = 0 });
    try testing.expect(model.git_commit_active);
    try testing.expect(model.git_commit_then_push);
    try testing.expect(model.has_git_commit_pushing());
    try testing.expect(model.has_git_commit_committing_and_pushing());
    try testing.expect(!model.has_git_commit_push_only());
    try testing.expect(!model.has_git_commit_committing());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Committing and pushing…");
    try testing.expect(findByText(tree.root, .text, "Pushing…") == null);
    try testing.expect(findByText(tree.root, .text, "Committing…") == null);
    try testing.expect(findByText(tree.root, .text, "Amending…") == null);
    try testing.expect(findByText(tree.root, .text, "Generating…") == null);

    main.update(&model, .cancel_git_commit, &fx);
    try testing.expect(!model.git_commit_active);
    try testing.expect(!model.has_git_commit_committing_and_pushing());
    try testing.expect(!model.has_git_commit_pushing());
}

test "Commit card Amend hides Commit and Push and Push and paints Amending" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-commit-amend-ui", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("commit amend ui", .fx);
    model.selected = id;
    if (model.sessionById(id)) |session| session.setProjectPath(project);
    model.git_dirty_count = 1;
    model.git_dirty_key = 0;
    model.git_has_staged = false;
    model.git_has_unstaged = true;
    model.git_ahead_behind_ready = true;
    model.git_ahead_behind_has_upstream = true;
    model.git_ahead_behind_ahead = 1;
    model.git_remotes_ready = true;
    model.git_has_remote = true;

    main.update(&model, .start_git_commit, &fx);
    try testing.expect(model.git_commit_active);
    try testing.expect(!model.git_commit_amend);
    try testing.expect(model.can_commit_and_push_git());
    try testing.expect(model.can_git_commit_push_only());
    var tree = try buildTree(arena, &model);
    const amend_off = try expectButtonMsg(tree, "Amend", .toggle_git_commit_amend);
    try testing.expect(!amend_off.state.selected);
    _ = try expectButtonMsg(tree, "Commit and Push", .confirm_git_commit_and_push);
    _ = try expectButtonMsg(tree, "Push", .confirm_git_commit_push);
    try testing.expect(findByText(tree.root, .text, "Amending…") == null);

    main.update(&model, tree.msgForPointer(amend_off.id, .up).?, &fx);
    try testing.expect(model.git_commit_amend);
    try testing.expect(!model.can_commit_and_push_git());
    try testing.expect(!model.can_git_commit_push_only());
    try testing.expect(model.can_push_git_branch());
    tree = try buildTree(arena, &model);
    const amend_on = try expectButtonMsg(tree, "Amend", .toggle_git_commit_amend);
    try testing.expect(amend_on.state.selected);
    try testing.expect(findByText(tree.root, .button, "Commit and Push") == null);
    try testing.expect(findByText(tree.root, .button, "Push") == null);
    _ = try expectButtonMsg(tree, "Commit", .confirm_git_commit);

    main.update(&model, .{ .git_commit_edit = .{ .insert_text = "wrap the dirty probe" } }, &fx);
    main.update(&model, .confirm_git_commit, &fx);
    try testing.expect(model.has_git_commit_amending());
    try testing.expect(!model.has_git_commit_committing());
    try testing.expect(!model.has_git_commit_committing_and_pushing());
    try testing.expect(!model.has_git_commit_push_only());
    try testing.expect(!model.has_git_commit_generate());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Amending…");
    try testing.expect(findByText(tree.root, .text, "Generating…") == null);
    try testing.expect(findByText(tree.root, .text, "Committing…") == null);
    try testing.expect(findByText(tree.root, .text, "Committing and pushing…") == null);
    try testing.expect(findByText(tree.root, .text, "Pushing…") == null);

    const add = findPendingGitCommitAdd(&fx, model.git_commit_key) orelse return error.MissingGitAddSpawn;
    git_commit.handleCommitExit(&model, &fx, .{ .key = add.key, .reason = .exited, .code = 0 });
    try testing.expect(model.has_git_commit_amending());
    const preflight = findPendingGitCommitCachedQuiet(&fx, model.git_commit_key) orelse return error.MissingGitCachedQuietSpawn;
    git_commit.handleCommitExit(&model, &fx, .{ .key = preflight.key, .reason = .exited, .code = 1 });
    try testing.expect(model.has_git_commit_amending());
    const amend_spawn = findPendingGitCommitAmend(&fx, model.git_commit_key) orelse return error.MissingGitAmendSpawn;
    try testing.expect(git_commit.isGitCommitAmendArgv(amend_spawn.argv));
    try testing.expect(!git_commit.isGitCommitArgv(amend_spawn.argv));
    try testing.expectEqualStrings(git_commit.git_amend_flag, amend_spawn.argv[7]);
    try testing.expectEqualStrings("wrap the dirty probe", amend_spawn.argv[9]);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Amending…");
    try testing.expect(findByText(tree.root, .text, "Committing…") == null);

    git_commit.handleCommitExit(&model, &fx, .{ .key = amend_spawn.key, .reason = .exited, .code = 0 });
    try testing.expect(!model.git_commit_active);
    try testing.expect(!model.has_git_commit_amending());
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
}

test "confirm New worktree one-shots git worktree add -b; success retargets project_path; failure sets status" {
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-wt-add", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);
    var home_buf: [256]u8 = undefined;
    const home = try std.fmt.bufPrint(&home_buf, "/tmp/faku-wt-home-{s}", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, home);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    model.setHome(home);
    const id = model.addSession("worktree add", .fx);
    model.selected = id;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try fx.feedLine(branch.key, "main\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(project, model.selectedProjectPath());

    main.update(&model, .start_git_worktree_create, &fx);
    try testing.expect(model.git_worktree_create_active);
    try testing.expectEqualStrings("worktree-add", model.git_worktree_create());
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "not a branch" } }, &fx);
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_base_key);
    try testing.expect(model.git_worktree_create_active);
    try testing.expectEqualStrings(project, model.selectedProjectPath());

    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat/foo" } }, &fx);
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_base_key);

    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat-new" } }, &fx);
    model.phase = .streaming;
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_base_key);
    model.phase = .idle;
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    const probe_key = model.git_worktree_base_key;
    try testing.expect(probe_key >= main.git_worktree_base_key_first);
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(probe_key, model.git_worktree_base_key);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try finishWorktreeBaseProbe(&fx, &model, "origin/main\n", 0);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_base_key);
    const created = findGitWorktreeAddSpawnKey(&fx, model.git_worktree_add_key) orelse return error.MissingGitWorktreeAddSpawn;
    try expectGitWorktreeAddArgv(created, project, home, "feat-new", "main");
    try testing.expect(model.git_worktree_create_active);
    try testing.expectEqualStrings(project, model.selectedProjectPath());

    const add_key = model.git_worktree_add_key;
    main.update(&model, .confirm_git_worktree_create, &fx);
    try testing.expectEqual(add_key, model.git_worktree_add_key);
    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(add_key, model.git_worktree_add_key);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);

    var dest_buf: [main.max_project_path]u8 = undefined;
    const dest = git_checkout.worktreeDestPath(home, project, "feat-new", dest_buf[0..]) orelse return error.MissingDest;
    try std.Io.Dir.cwd().createDirPath(testing.io, dest);
    try fx.feedExit(created.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expect(!model.git_worktree_create_active);
    try testing.expectEqualStrings(dest, model.selectedProjectPath());
    try testing.expect(findGitBranchSpawnKey(&fx, model.git_branch_key) != null);
    try testing.expect(findGitDirtySpawnKey(&fx, model.git_dirty_key) != null);
    try testing.expect(findGitNumstatSpawnKey(&fx, model.git_numstat_key) != null);
    try testing.expect(findFileMentionSpawnKey(&fx, model.file_mention_key) != null);
    try testing.expect(findGitBranchListSpawnKey(&fx, model.git_branch_list_key) != null);

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const reset_branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchReset;
    try fx.feedLine(reset_branch.key, "main\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(project, model.selectedProjectPath());

    main.update(&model, .start_git_worktree_create, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat-blocked" } }, &fx);
    main.update(&model, .confirm_git_worktree_create, &fx);
    try finishWorktreeBaseProbe(&fx, &model, "", 1);
    try failWorktreeAddFirstThenExhaust(&fx, &model, project, home, "feat-blocked", "main");

    model.clearAttachStatus();
    main.writeFixed(&model.git_branch_storage, &model.git_branch_len, "a1b2c3d");
    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat-head" } }, &fx);
    main.update(&model, .confirm_git_worktree_create, &fx);
    try finishWorktreeBaseProbe(&fx, &model, "", 1);
    try failWorktreeAddFirstThenExhaust(&fx, &model, project, home, "feat-head", "");

    model.clearAttachStatus();
    main.update(&model, .{ .git_worktree_create_edit = .clear }, &fx);
    main.update(&model, .{ .git_worktree_create_edit = .{ .insert_text = "feat-cancel" } }, &fx);
    main.update(&model, .confirm_git_worktree_create, &fx);
    const stale_probe = findGitWorktreeBaseSpawnKey(&fx, model.git_worktree_base_key) orelse return error.MissingGitWorktreeBaseCancel;
    try testing.expect(stale_probe.key >= main.git_worktree_base_key_first);
    main.update(&model, .cancel_git_worktree_create, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_base_key);
    try testing.expect(!model.git_worktree_create_active);
    try testing.expectEqual(@as(u64, 0), model.git_worktree_add_key);
    try testing.expectEqualStrings(project, model.selectedProjectPath());
    try testing.expect(findGitWorktreeAddSpawnKey(&fx, model.git_worktree_add_key) == null);
}

