}

fn findGitReviewDiffSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and review_diff.isGitReviewDiffArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn findGitReviewHunkSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and review_diff.isGitReviewHunkArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn expectGitReviewUncommittedArgv(argv: []const []const u8) !void {
    try testing.expect(review_diff.isGitReviewUncommittedArgv(argv));
    try testing.expect(review_diff.isGitReviewDiffArgv(argv));
    try testing.expect(!review_diff.isGitReviewHunkArgv(argv));
    switch (builtin.os.tag) {
        .windows => {
            try testing.expectEqual(@as(usize, review_diff.windows_argv_len_uncommitted), argv.len);
            try testing.expectEqualStrings(review_diff.powershell_bin, argv[0]);
            try testing.expectEqualStrings(review_diff.powershell_noprofile, argv[1]);
            try testing.expectEqualStrings(review_diff.powershell_command, argv[2]);
            try testing.expectEqualStrings(review_diff.powershell_uncommitted_untracked_script, argv[3]);
            try testing.expectEqualStrings(review_diff.powershell_args_flag, argv[4]);
            try testing.expect(argv[5].len > 0);
            try testing.expect(std.mem.indexOf(u8, argv[3], argv[5]) == null);
            try testing.expect(std.mem.indexOf(u8, argv[3], "$args[0]") != null);
            try testing.expect(std.mem.indexOf(u8, argv[3], review_diff.git_name_status) != null);
            try testing.expect(std.mem.indexOf(u8, argv[3], review_diff.git_ls_files_others) != null);
            try testing.expect(std.mem.indexOf(u8, argv[3], "--numstat") == null);
        },
        else => {
            try testing.expectEqual(review_diff.argv_len_uncommitted, argv.len);
            try testing.expectEqualStrings(review_diff.uncommitted_untracked_script, argv[7]);
            try testing.expect(std.mem.indexOf(u8, argv[2], "HEAD") == null);
            try testing.expect(std.mem.indexOf(u8, argv[2], review_diff.uncommitted_untracked_script) == null);
        },
    }
}

fn expectGitReviewUntrackedHunkArgv(argv: []const []const u8, path: []const u8) !void {
    try testing.expect(review_diff.isGitReviewHunkArgv(argv));
    try testing.expect(!review_diff.isGitReviewDiffArgv(argv));
    try testing.expectEqualStrings(path, argv[argv.len - 1]);
    switch (builtin.os.tag) {
        .windows => {
            try testing.expectEqual(review_diff.windows_argv_len_hunk_untracked, argv.len);
            try testing.expectEqualStrings(review_diff.windows_git_bin, argv[0]);
            try testing.expectEqualStrings(review_diff.git_no_index, argv[4]);
            try testing.expectEqualStrings(review_diff.git_pathspec_end, argv[5]);
            try testing.expectEqualStrings(review_diff.git_nul, argv[6]);
            try testing.expect(std.mem.indexOf(u8, argv[2], path) == null);
            try testing.expect(std.mem.indexOf(u8, argv[2], review_diff.git_nul) == null);
        },
        else => {
            try testing.expectEqual(review_diff.unix_argv_len_hunk_untracked, argv.len);
            try testing.expectEqualStrings(review_diff.git_no_index, argv[7]);
            try testing.expectEqualStrings(review_diff.git_pathspec_end, argv[8]);
            try testing.expectEqualStrings(review_diff.git_dev_null, argv[9]);
            try testing.expect(std.mem.indexOf(u8, argv[2], path) == null);
            try testing.expect(std.mem.indexOf(u8, argv[2], review_diff.git_dev_null) == null);
        },
    }
}

fn finishGitRemotesIfInFlight(fx: *Effects, model: *Model, line: []const u8) !void {
    if (model.git_remotes_key == 0) return;
    const spawn = findGitRemotesSpawnKey(fx, model.git_remotes_key) orelse return error.MissingGitRemotesSpawn;
    try testing.expect(spawn.key >= main.git_remotes_key_first);
    try testing.expect(spawn.key != model.git_push_key);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_checkout.git_remote_cmd) == null);
    if (line.len > 0) {
        try fx.feedLine(spawn.key, line);
        drainEffects(model, fx);
    }
    try fx.feedExit(spawn.key, 0);
    drainEffects(model, fx);
}

fn finishAheadBehindNoUpstream(fx: *Effects, model: *Model) !void {
    const spawn = findGitAheadBehindSpawnKey(fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindSpawn;
    try fx.feedExit(spawn.key, 128);
    drainEffects(model, fx);
    try finishGitRemotesIfInFlight(fx, model, "origin\n");
    try testing.expect(model.can_push_git_branch());
}

fn finishAheadBehindLine(fx: *Effects, model: *Model, line: []const u8) !void {
    const spawn = findGitAheadBehindSpawnKey(fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindSpawn;
    try fx.feedLine(spawn.key, line);
    drainEffects(model, fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(model, fx);
}

fn expectGitAheadBehindArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(git_ahead_behind.isGitAheadBehindArgv(spawn.argv));
    try testing.expectEqual(@as(usize, 10), spawn.argv.len);
    try testing.expectEqualStrings(git_ahead_behind.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings("-c", spawn.argv[1]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings("sh", spawn.argv[3]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(git_ahead_behind.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(git_ahead_behind.git_rev_list_cmd, spawn.argv[6]);
    try testing.expectEqualStrings(git_ahead_behind.git_left_right, spawn.argv[7]);
    try testing.expectEqualStrings(git_ahead_behind.git_count, spawn.argv[8]);
    try testing.expectEqualStrings(git_ahead_behind.git_upstream_range, spawn.argv[9]);
    try testing.expectEqualStrings("@{upstream}...HEAD", spawn.argv[9]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[2], git_ahead_behind.git_upstream_range) == null);
    try testing.expect(spawn.key != main.fx_ask_key);
    try testing.expect(spawn.key != main.fx_probe_key);
    try testing.expect(spawn.key != main.maximize_window_key);
    try testing.expect(spawn.key != main.pick_image_key);
    try testing.expect(spawn.key != main.pick_folder_key);
    try testing.expect(spawn.key != main.copy_turn_key);
    try testing.expect(spawn.key != main.git_branch_key_first);
    try testing.expect(spawn.key != main.git_dirty_key_first);
    try testing.expect(spawn.key != main.git_numstat_key_first);
    try testing.expect(spawn.key != main.git_push_key_first);
    try testing.expect(spawn.key != main.git_worktree_add_key_first);
    try testing.expect(spawn.key != main.file_mention_key_first);
    try testing.expect(spawn.key >= main.git_ahead_behind_key_first);
    try testing.expect(spawn.key < main.file_mention_key_first);
    try testing.expect(!git_branch.isGitBranchArgv(spawn.argv));
    try testing.expect(!git_dirty.isGitDirtyArgv(spawn.argv));
    try testing.expect(!git_numstat.isGitNumstatArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitUpstreamArgv(spawn.argv));
    try testing.expect(!git_checkout.isGitWorktreeAddArgv(spawn.argv));
    try testing.expect(!file_mention.isGitLsFilesArgv(spawn.argv));
}

