    try fx.feedLine(spawn.key, "0\t2\n");
    drainEffects(&model, &fx);
    try testing.expect(model.has_git_ahead_behind());
    try testing.expectEqualStrings("↑2", model.git_ahead_behind_label());
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2", model.git_ahead_behind_label());

    var tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .button, project);
    _ = try expectByText(tree.root, .text, "↑2");
    try testing.expect(findByText(tree.root, .text, "synced") == null);
    try testing.expect(findByText(tree.root, .text, "0 ahead") == null);
    try testing.expect(findByText(tree.root, .button, "Local") == null);

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindBehind;
    try expectGitAheadBehindArgv(spawn, project);
    try testing.expect(!model.has_git_ahead_behind());
    try fx.feedLine(spawn.key, "3\t0\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↓3", model.git_ahead_behind_label());
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↓3", model.git_ahead_behind_label());

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "↓3");
    try testing.expect(findByText(tree.root, .text, "↑2") == null);

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindBoth;
    try fx.feedLine(spawn.key, "1\t2\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2 ↓1", model.git_ahead_behind_label());
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2 ↓1", model.git_ahead_behind_label());

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "↑2 ↓1");
    try testing.expect(findByText(tree.root, .text, "synced") == null);
}

test "git ahead/behind label is omitted for empty missing rejected zero and no-upstream" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/ahead-omit", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("omit ahead", .fx);
    model.selected = id;

    try testing.expect(model.project_is_local());
    git_ahead_behind.refresh(&model, &fx);
    try testing.expect(findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) == null);
    try testing.expect(!model.has_git_ahead_behind());

    main.update(&model, .{ .project_path_edit = .{ .insert_text = ".zig-cache/tmp/faku-ahead-missing" } }, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_ahead_behind_key);
    try testing.expect(!model.has_git_ahead_behind());

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    var spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindSpawn;
    try expectGitAheadBehindArgv(spawn, project);
    try fx.feedLine(spawn.key, "   \n");
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindZero;
    try fx.feedLine(spawn.key, "0\t0\n");
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindFail;
    try fx.feedLine(spawn.key, "2\t1\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑1 ↓2", model.git_ahead_behind_label());
    try fx.feedExit(spawn.key, 128);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindNoUpstream;
    try fx.feedExit(spawn.key, 1);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    git_ahead_behind.refresh(&model, &fx);
    spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindRejected;
    try fx.feedLine(spawn.key, "0\t2\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2", model.git_ahead_behind_label());
    try fx.feedExitReason(spawn.key, 0, .rejected);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_ahead_behind());

    const tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .button, project);
    try testing.expect(findByText(tree.root, .text, "↑2") == null);
    try testing.expect(findByText(tree.root, .text, "↑1 ↓2") == null);
    try testing.expect(findByText(tree.root, .text, "synced") == null);
    try testing.expect(findByText(tree.root, .text, "0 ahead") == null);
}

test "changing session or project_path cancels the previous ahead/behind probe" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var a_buf: [256]u8 = undefined;
    var b_buf: [256]u8 = undefined;
    const project_a = try std.fmt.bufPrint(&a_buf, ".zig-cache/tmp/{s}/ahead-a", .{tmp.sub_path[0..]});
    const project_b = try std.fmt.bufPrint(&b_buf, ".zig-cache/tmp/{s}/ahead-b", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project_a);
    try std.Io.Dir.cwd().createDirPath(testing.io, project_b);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const first = model.addSession("first ahead", .fx);
    const second = model.addSession("second ahead", .fx);
    model.selected = first;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project_a } }, &fx);
    const first_spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindSpawn;
    const first_key = first_spawn.key;
    try expectGitAheadBehindArgv(first_spawn, project_a);
    const first_remotes = findGitRemotesSpawnKey(&fx, model.git_remotes_key) orelse return error.MissingGitRemotesSpawn;
    const first_remotes_key = first_remotes.key;
    try testing.expect(first_remotes_key >= main.git_remotes_key_first);
    const first_toplevel = findGitToplevelSpawnKey(&fx, model.git_toplevel_key) orelse return error.MissingGitToplevelSpawn;
    try testing.expect(first_toplevel.key >= main.git_toplevel_key_first);
    try testing.expect(first_toplevel.key > first_remotes_key);
    const first_common = findGitCommonDirSpawnKey(&fx, model.git_common_dir_key) orelse return error.MissingGitCommonDirSpawn;
    try testing.expect(first_common.key >= main.git_common_dir_key_first);
    try testing.expect(first_common.key > first_toplevel.key);
    switch (builtin.os.tag) {
        .windows => {
            try testing.expectEqualStrings(git_common_dir.git_common_dir_flag, first_common.argv[first_common.argv.len - 1]);
        },
        else => {
            try testing.expectEqualStrings(git_common_dir.git_common_dir_flag, first_common.argv[7]);
            try testing.expect(std.mem.indexOf(u8, first_common.argv[2], git_common_dir.git_common_dir_flag) == null);
        },
    }
    try fx.feedLine(first_key, "0\t2\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2", model.git_ahead_behind_label());

    main.update(&model, .{ .select = second }, &fx);
    try testing.expectEqual(second, model.selected);
    try testing.expect(!model.has_git_ahead_behind());
    try testing.expectEqual(@as(u64, 0), model.git_ahead_behind_key);
    try testing.expectEqual(@as(u64, 0), model.git_remotes_key);
    try testing.expect(!model.git_has_remote);
    try testing.expect(!model.git_remotes_ready);
    try testing.expectEqual(@as(u64, 0), model.git_toplevel_key);
    try testing.expect(!model.git_toplevel_ready);
    try testing.expectEqual(@as(usize, 0), model.git_toplevel_path_len);
    try testing.expectEqual(@as(u64, 0), model.git_common_dir_key);
    try testing.expect(!model.git_common_dir_ready);
    try testing.expectEqual(@as(usize, 0), model.git_common_dir_path_len);
    try testing.expectError(error.EffectNotFound, fx.feedLine(first_key, "1\t0\n"));
    git_ahead_behind.applyLine(&model, .{ .key = first_key, .line = "1\t0" });
    try testing.expect(!model.has_git_ahead_behind());

    main.update(&model, .{ .select = first }, &fx);
    const again = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindAgain;
    try testing.expect(again.key != first_key);
    try expectGitAheadBehindArgv(again, project_a);
    try testing.expect(!model.has_git_ahead_behind());
    try fx.feedLine(again.key, "0\t2\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2", model.git_ahead_behind_label());

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project_b } }, &fx);
    try testing.expect(!model.has_git_ahead_behind());
    const second_spawn = findGitAheadBehindSpawnKey(&fx, model.git_ahead_behind_key) orelse return error.MissingGitAheadBehindSecond;
    try testing.expect(second_spawn.key != again.key);
    try expectGitAheadBehindArgv(second_spawn, project_b);

    try testing.expectError(error.EffectNotFound, fx.feedLine(again.key, "3\t0\n"));
    git_ahead_behind.applyLine(&model, .{ .key = again.key, .line = "3\t0" });
    try testing.expect(!model.has_git_ahead_behind());

    try fx.feedLine(second_spawn.key, "1\t2\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("↑2 ↓1", model.git_ahead_behind_label());

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    try testing.expect(!model.has_git_ahead_behind());
    try testing.expect(model.project_is_local());

    const tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .button, "choose a project");
    _ = try expectByText(tree.root, .button, "Local");
    try testing.expect(findByText(tree.root, .text, "↑2") == null);
    try testing.expect(findByText(tree.root, .text, "↑2 ↓1") == null);
    try testing.expect(findByText(tree.root, .text, "synced") == null);
}

test "Push… follows Waku can_push: ahead or no-upstream with remotes; hides in-flight and ahead 0" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/git-can-push", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("can push", .fx);
    model.selected = id;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try fx.feedLine(branch.key, "main\n");
    drainEffects(&model, &fx);
    try testing.expect(model.can_pick_git_branch());
    try testing.expect(!model.can_push_git_branch());

    main.update(&model, .toggle_git_branch_picker, &fx);
    try testing.expect(model.git_branch_picker_open);
    var tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .menu_item, "Push…") == null);
    _ = try expectByText(tree.root, .menu_item, "Fetch…");

    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(!model.git_branch_picker_open);

    try finishAheadBehindLine(&fx, &model, "0\t2\n");
    try testing.expect(model.can_push_git_branch());
    try testing.expect(model.has_git_ahead_behind());
    main.update(&model, .toggle_git_branch_picker, &fx);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .menu_item, "Push…");
    main.update(&model, .close_git_branch_picker, &fx);

    git_ahead_behind.refresh(&model, &fx);
    try testing.expect(!model.can_push_git_branch());
    try finishAheadBehindLine(&fx, &model, "3\t0\n");
    try testing.expect(!model.can_push_git_branch());
    try testing.expectEqualStrings("↓3", model.git_ahead_behind_label());
    main.update(&model, .toggle_git_branch_picker, &fx);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .menu_item, "Push…") == null);
    main.update(&model, .start_git_push, &fx);
    try testing.expectEqual(@as(u64, 0), model.git_push_key);
    try testing.expect(!model.git_branch_picker_open);

    git_ahead_behind.refresh(&model, &fx);
    try finishAheadBehindLine(&fx, &model, "0\t0\n");
    try testing.expect(!model.can_push_git_branch());
    try testing.expect(!model.has_git_ahead_behind());
    main.update(&model, .toggle_git_branch_picker, &fx);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .menu_item, "Push…") == null);
    main.update(&model, .close_git_branch_picker, &fx);

    git_ahead_behind.refresh(&model, &fx);
    try testing.expect(!model.can_push_git_branch());
    try finishAheadBehindNoUpstream(&fx, &model);
    try testing.expect(model.can_push_git_branch());
    try testing.expect(!model.has_git_ahead_behind());
    main.update(&model, .toggle_git_branch_picker, &fx);
    tree = try buildTree(arena, &model);
    const push_item = try expectByText(tree.root, .menu_item, "Push…");
    try testing.expectEqual(Msg.start_git_push, tree.msgForPointer(push_item.id, .up).?);

    main.update(&model, .start_git_push, &fx);
    try testing.expect(model.git_push_confirm_active);
    main.update(&model, .confirm_git_push, &fx);
    try testing.expect(findGitUpstreamSpawnKey(&fx, model.git_push_key) != null);
}

fn findFileMentionSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and file_mention.isGitLsFilesArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn findFileMentionWalkSpawnKey(fx: *Effects, key: u64) ?@TypeOf(fx.pendingSpawnAt(0).?) {
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (spawn.key == key and file_mention.isWalkArgv(spawn.argv)) return spawn;
    }
    return null;
}

fn countFileMentionWalkSpawns(fx: *Effects) usize {
    var n: usize = 0;
    var i: usize = 0;
    while (fx.pendingSpawnAt(i)) |spawn| : (i += 1) {
        if (file_mention.isWalkArgv(spawn.argv)) n += 1;
    }
    return n;
}

fn expectFileMentionArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(file_mention.isGitLsFilesArgv(spawn.argv));
    try testing.expectEqualStrings(file_mention.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(file_mention.git_bin, spawn.argv[5]);
    try testing.expectEqualStrings(file_mention.git_ls_files_cmd, spawn.argv[6]);
    try testing.expectEqualStrings(file_mention.git_ls_files_cached, spawn.argv[7]);
    try testing.expectEqualStrings(file_mention.git_ls_files_others, spawn.argv[8]);
    try testing.expectEqualStrings(file_mention.git_ls_files_exclude_standard, spawn.argv[9]);
    try testing.expect(spawn.key != main.fx_ask_key);
    try testing.expect(spawn.key != main.fx_probe_key);
    try testing.expect(spawn.key != main.maximize_window_key);
    try testing.expect(spawn.key != main.pick_image_key);
    try testing.expect(spawn.key != main.pick_folder_key);
    try testing.expect(spawn.key != main.reveal_folder_key);
    try testing.expect(spawn.key != main.open_terminal_key);
    try testing.expect(spawn.key != main.open_editor_key);
    try testing.expect(spawn.key != main.copy_turn_key);
    try testing.expect(spawn.key >= main.file_mention_key_first);
    try testing.expect(spawn.key != main.git_dirty_key_first);
    try testing.expect(spawn.key != main.git_numstat_key_first);
    try testing.expect(spawn.key != main.git_push_key_first);
    try testing.expect(!git_branch.isGitBranchArgv(spawn.argv));
    try testing.expect(!git_dirty.isGitDirtyArgv(spawn.argv));
    try testing.expect(!git_numstat.isGitNumstatArgv(spawn.argv));
    try testing.expect(!file_mention.isWalkArgv(spawn.argv));
}

fn expectFileMentionWalkArgv(spawn: anytype, cwd: []const u8) !void {
    try testing.expect(file_mention.isWalkArgv(spawn.argv));
    try testing.expect(!file_mention.isGitLsFilesArgv(spawn.argv));
    try testing.expect(!git_branch.isGitBranchArgv(spawn.argv));
    try testing.expect(!git_dirty.isGitDirtyArgv(spawn.argv));
    try testing.expect(!git_numstat.isGitNumstatArgv(spawn.argv));
    try testing.expectEqualStrings(file_mention.sh_bin, spawn.argv[0]);
    try testing.expectEqualStrings(main.fx_ask_chdir_script, spawn.argv[2]);
    try testing.expectEqualStrings(cwd, spawn.argv[4]);
    try testing.expectEqualStrings(file_mention.sh_bin, spawn.argv[5]);
    try testing.expectEqualStrings("-c", spawn.argv[6]);
    try testing.expectEqualStrings(file_mention.find_walk_script, spawn.argv[7]);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[7], file_mention.find_maxdepth_flag) != null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[7], file_mention.find_maxdepth) != null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[7], file_mention.find_dot_star) != null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[7], file_mention.find_prune) != null);
    try testing.expect(std.mem.indexOf(u8, spawn.argv[7], file_mention.find_type_file) != null);
    inline for (file_mention.walk_skip_names) |name| {
        try testing.expect(std.mem.indexOf(u8, spawn.argv[7], name) != null);
    }
    try testing.expect(spawn.key >= main.file_mention_key_first);
}

test "composer @ mention card filters tracked files; insert replaces last token; slash stays authoritative" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-file-mention", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.task_state_loaded = true;
    model.setStoreDir(dir);
    model.store_io = testing.io;
    model.fx_available = true;
    model.fx_probe_started = true;
    model.setFxPath("fx");
    const id = model.addSession("file mention", .fx);
    _ = model.appendTurn(id, .user, "already started");
    model.selected = id;
    if (model.sessionById(id)) |session| {
        session.appendAvailableCommand("commit", "Create a commit");
        session.appendAvailableCommand("compact", "Compact the conversation");
    }
    try store.saveSession(&model, id, testing.allocator, testing.io);

    try testing.expect(!model.mentions_list_open());
    try testing.expectEqual(@as(usize, 0), model.mention_rows(arena).len);

    main.update(&model, .{ .draft_edit = .{ .insert_text = "see @src" } }, &fx);
    try testing.expectEqualStrings("see @src", model.draft());
    try testing.expect(!model.mentions_list_open());
    try testing.expectEqual(@as(usize, 0), model.mention_rows(arena).len);
    var tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "src/main.zig") == null);

    file_mention.applyStdoutPaths(&model,
        \\src/main.zig
        \\src/composer.zig
        \\src/file_mention.zig
        \\README.md
    );
    try testing.expect(model.mentions_list_open());
    {
        const rows = model.mention_rows(arena);
        try testing.expectEqual(@as(usize, 4), rows.len);
        try testing.expectEqualStrings("src/", rows[0].path);
        try testing.expectEqualStrings("src", rows[0].name);
        try testing.expectEqualStrings("", rows[0].parent);
