test "composer Enter confirms first @ mention; Esc dismisses; Send button still sends" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var dir_buf: [256]u8 = undefined;
    const dir = try std.fmt.bufPrint(&dir_buf, ".zig-cache/tmp/{s}/faku-mention-enter", .{tmp.sub_path[0..]});

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    try expectComposerEnterMarkup();

    var model = Model{};
    model.task_state_loaded = true;
    model.setStoreDir(dir);
    model.store_io = testing.io;
    model.fx_available = true;
    model.fx_probe_started = true;
    model.setFxPath("fx");
    const id = model.addSession("mention enter", .fx);
    _ = model.appendTurn(id, .user, "already started");
    model.selected = id;
    try store.saveSession(&model, id, testing.allocator, testing.io);
    file_mention.applyStdoutPaths(&model,
        \\notes/email.md
        \\src/lib/util.zig
        \\README.md
        \\src/main.zig
    );

    main.update(&model, .{ .draft_edit = .{ .insert_text = "@mai" } }, &fx);
    try testing.expect(model.mentions_list_open());
    try testing.expect(!model.autocomplete_dismissed);
    try testing.expectEqual(@as(u32, 0), model.autocomplete_highlight);
    {
        const rows = model.mention_rows(arena);
        try testing.expectEqual(@as(usize, 2), rows.len);
        try testing.expect(rows[0].selected);
        try testing.expect(!rows[1].selected);
        try testing.expectEqualStrings("src/main.zig", rows[0].path);
        try testing.expectEqual(@as(u32, 4), rows[0].id);
    }

    const tree = try buildTree(arena, &model);
    if (findByKind(tree.root, .textarea)) |composer| {
        try testing.expectEqualStrings("@mai", composer.text);
    } else return error.WidgetNotFound;
    const first_row = try expectButton(tree.root, "src/main.zig");
    if (@hasField(canvas.Widget, "selected")) {
        try testing.expect(first_row.selected);
        const second_row = try expectButton(tree.root, "notes/email.md");
        try testing.expect(!second_row.selected);
    }

    main.update(&model, .composer_enter, &fx);
    try testing.expectEqualStrings("@src/main.zig ", model.draft());
    try testing.expect(model.composer_active);
    try testing.expect(!model.mentions_list_open());
    try testing.expect(!model.autocomplete_dismissed);
    try testing.expectEqual(@as(usize, 0), fx.pendingSpawnCount());
    try testing.expect(!model.fx_spawn_live);
    try testing.expect(!model.is_streaming());
    try testing.expectEqual(@as(usize, 1), countRole(&model, .user));

    var loaded = Model{};
    loaded.setStoreDir(dir);
    loaded.store_io = testing.io;
    try testing.expectEqual(store.LoadKind.loaded, store.loadCatalog(&loaded, testing.allocator, testing.io));
    try testing.expectEqualStrings("@src/main.zig ", loaded.draft());
    try testing.expectEqual(@as(u32, 0), loaded.autocomplete_highlight);
    try testing.expect(!loaded.autocomplete_dismissed);

    model.draft_buffer.clear();
    main.update(&model, .{ .draft_edit = .{ .insert_text = "plain send" } }, &fx);
    try testing.expect(!model.mentions_list_open());
    try testing.expect(!model.commands_list_open());
    main.update(&model, .composer_enter, &fx);
    try testing.expect(model.is_streaming());
    try testing.expectEqualStrings("", model.draft());
    try testing.expectEqual(@as(usize, 2), countRole(&model, .user));
    main.update(&model, .stop_turn, &fx);
    try testing.expect(!model.is_streaming());

    main.update(&model, .{ .draft_edit = .{ .insert_text = "@mai" } }, &fx);
    try testing.expect(model.mentions_list_open());
    try testing.expectEqualStrings("@mai", model.draft());
    main.update(&model, .send, &fx);
    try testing.expect(model.is_streaming());
    try testing.expectEqualStrings("", model.draft());
    try testing.expectEqual(@as(usize, 3), countRole(&model, .user));
    main.update(&model, .stop_turn, &fx);
    try testing.expect(!model.is_streaming());

    main.update(&model, .{ .draft_edit = .{ .insert_text = "keep streaming" } }, &fx);
    main.update(&model, .send, &fx);
    try testing.expect(model.is_streaming());
    try testing.expect(model.sessionById(id).?.busy);
    main.update(&model, .{ .draft_edit = .{ .insert_text = "@mai" } }, &fx);
    try testing.expect(model.mentions_list_open());
    try testing.expectEqualStrings("@mai", model.draft());
    const escape = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "escape" };
    try testing.expectEqual(Msg.stop, keys.onKey(escape).?);
    main.update(&model, keys.onKey(escape).?, &fx);
    try testing.expect(model.autocomplete_dismissed);
    try testing.expect(!model.mentions_list_open());
    try testing.expectEqualStrings("@mai", model.draft());
    try testing.expect(model.is_streaming());
    try testing.expect(model.sessionById(id).?.busy);

    main.update(&model, .{ .draft_edit = .{ .insert_text = "n" } }, &fx);
    try testing.expectEqualStrings("@main", model.draft());
    try testing.expect(!model.autocomplete_dismissed);
    try testing.expect(model.mentions_list_open());
    try testing.expectEqual(@as(u32, 0), model.autocomplete_highlight);
}

fn expectComposerEnterMarkup() !void {
    inline for (Msg.view_unbound) |name| {
        try testing.expect(!std.mem.eql(u8, name, "composer_enter"));
    }
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-submit=\"composer_enter\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "on-press=\"send\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "selected=\"{c.selected}\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "selected=\"{sk.selected}\"") != null);
    try testing.expect(std.mem.indexOf(u8, main.app_markup, "selected=\"{m.selected}\"") != null);
}

test "git ls-files sidecar argv and first-N stdout; empty missing rejected skip" {
    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/ls-proj", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("ls files", .fx);
    model.selected = id;

    file_mention.refresh(&model, &fx);
    try testing.expect(findFileMentionSpawnKey(&fx, model.file_mention_key) == null);
    try testing.expect(findFileMentionWalkSpawnKey(&fx, model.file_mention_key) == null);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);

    main.update(&model, .{ .project_path_edit = .{ .insert_text = ".zig-cache/tmp/faku-ls-missing" } }, &fx);
    try testing.expectEqual(@as(u64, 0), model.file_mention_key);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    var mention = findFileMentionSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionSpawn;
    try expectFileMentionArgv(mention, project);
    try testing.expect(findFileMentionWalkSpawnKey(&fx, model.file_mention_key) == null);
    const branch = findGitBranchSpawnKey(&fx, model.git_branch_key) orelse return error.MissingGitBranchSpawn;
    try expectGitBranchArgv(branch, project);
    try testing.expect(mention.key != branch.key);
    const dirty = findGitDirtySpawnKey(&fx, model.git_dirty_key) orelse return error.MissingGitDirtySpawn;
    try expectGitDirtyArgv(dirty, project);
    try testing.expect(mention.key != dirty.key);
    try testing.expect(branch.key != dirty.key);
    const numstat = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try expectGitNumstatArgv(numstat, project);
    try testing.expect(mention.key != numstat.key);
    try testing.expect(branch.key != numstat.key);
    try testing.expect(dirty.key != numstat.key);

    try fx.feedLine(mention.key, "src/a.zig\n");
    drainEffects(&model, &fx);
    try fx.feedLine(mention.key, "src/b.zig\n");
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 2), model.file_mention_count);
    try testing.expectEqualStrings("src/a.zig", file_mention.cachedPath(&model, 0));
    try testing.expectEqualStrings("src/b.zig", file_mention.cachedPath(&model, 1));

    try fx.feedLine(branch.key, "main\n");
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("main", model.git_branch_label());

    try fx.feedExit(mention.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    try testing.expectEqualStrings("main", model.git_branch_label());
    var walk = findFileMentionWalkSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionWalkSpawn;
    try expectFileMentionWalkArgv(walk, project);
    try testing.expect(walk.key != mention.key);
    try testing.expect(walk.key != branch.key);
    try testing.expect(walk.key != dirty.key);
    try testing.expect(walk.key != numstat.key);

    try fx.feedLine(walk.key, "./src/a.zig\n");
    drainEffects(&model, &fx);
    try fx.feedLine(walk.key, "./src/b.zig\n");
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 2), model.file_mention_count);
    try testing.expectEqualStrings("src/a.zig", file_mention.cachedPath(&model, 0));
    try testing.expectEqualStrings("src/b.zig", file_mention.cachedPath(&model, 1));
    {
        var parents: [file_mention.max_file_mention_dirs][]const u8 = undefined;
        try testing.expectEqual(@as(usize, 1), file_mention.derivedDirParents(&model, &parents));
        try testing.expectEqualStrings("src", parents[0]);
    }
    try fx.feedExit(walk.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 2), model.file_mention_count);
    try testing.expectEqualStrings("src/a.zig", file_mention.cachedPath(&model, 0));
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));
    try testing.expectEqual(@as(u64, 0), model.file_mention_key);

    file_mention.refresh(&model, &fx);
    mention = findFileMentionSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionSpawn;
    try fx.feedExitReason(mention.key, 0, .rejected);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    walk = findFileMentionWalkSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionWalkSpawn;
    try expectFileMentionWalkArgv(walk, project);
    try fx.feedExit(walk.key, 1);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    try testing.expectEqual(@as(u64, 0), model.file_mention_key);
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));

    file_mention.refresh(&model, &fx);
    mention = findFileMentionSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionSpawn;
    try fx.feedExit(mention.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    try testing.expectEqual(@as(u64, 0), model.file_mention_key);
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));

    file_mention.refresh(&model, &fx);
    mention = findFileMentionSpawnKey(&fx, model.file_mention_key) orelse return error.MissingFileMentionSpawn;
    var overflow: [file_mention.max_file_mentions * 2 + 16]u8 = undefined;
    var n: usize = 0;
    var i: usize = 0;
    while (i < file_mention.max_file_mentions + 2) : (i += 1) {
        overflow[n] = 'p';
        n += 1;
        overflow[n] = '\n';
        n += 1;
    }
    try fx.feedLine(mention.key, overflow[0..n]);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, file_mention.max_file_mentions), model.file_mention_count);
    try fx.feedExit(mention.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqual(@as(u32, file_mention.max_file_mentions), model.file_mention_count);
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));

    main.update(&model, .{ .project_path_edit = .clear }, &fx);
    try testing.expectEqual(@as(u32, 0), model.file_mention_count);
    try testing.expectEqual(@as(u64, 0), model.file_mention_key);
    try testing.expectEqual(@as(usize, 0), countFileMentionWalkSpawns(&fx));
}

fn expectContextProgress(widget: canvas.Widget, expected: f32) !canvas.Widget {
    const progress = findByText(widget, .progress, "Context usage") orelse {
        std.debug.print("no progress labeled Context usage\n", .{});
        dumpTexts(widget, 0);
        return error.WidgetNotFound;
    };
    try testing.expectApproxEqAbs(expected, progress.value, 0.0001);
    return progress;
}

fn expectNoContextProgress(widget: canvas.Widget) !void {
    if (findByText(widget, .progress, "Context usage")) |_| {
        std.debug.print("idle composer still paints the empty usage blob\n", .{});
        return error.UnexpectedProgress;
    }
}

