test "Environment Compare closes the dropdown and opens a Review file-list card" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/env-compare-ui", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const first = model.addSession("env compare ui", .fx);
    const second = model.addSession("env compare other", .fx);
    model.selected = first;
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);

    main.update(&model, .toggle_environment_summary, &fx);
    try testing.expect(model.environment_summary_open);
    var tree = try buildTree(arena, &model);
    const compare = try expectByText(tree.root, .menu_item, "Compare");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(compare.id, .up).?);
    main.update(&model, tree.msgForPointer(compare.id, .up).?, &fx);
    try testing.expect(!model.environment_summary_open);
    try testing.expect(model.review_diff_active);
    try testing.expect(model.right_panel_open);
    try testing.expect(model.right_panel_tab_diff());
    try testing.expectEqual(review_diff.Source.uncommitted, model.review_diff_source);
    try testing.expect(model.review_diff_source_uncommitted());
    try testing.expect(!model.review_diff_source_branch());
    try testing.expect(!model.review_diff_source_staged());
    try testing.expect(!model.review_diff_source_unstaged());
    try testing.expect(!model.review_diff_source_committed());
    try testing.expect(!model.review_diff_source_last_turn());
    try testing.expect(model.review_diff_key >= main.review_diff_key_first);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());

    const spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffSpawn;
    try testing.expect(review_diff.isGitReviewDiffArgv(spawn.argv));
    try expectGitReviewUncommittedArgv(spawn.argv);
    try testing.expect(spawn.key >= main.review_diff_key_first);
    try testing.expect(spawn.key != model.git_ahead_behind_key);
    try testing.expect(spawn.key != model.git_common_dir_key);

    tree = try buildTree(arena, &model);
    try testing.expect(findByKind(tree.root, .dropdown_menu) == null);
    _ = try expectByText(tree.root, .text, "Review");
    _ = try expectByText(tree.root, .text, review_diff.comparing_status);
    _ = try expectButtonMsg(tree, "Cancel", .close_review_diff);
    const files_tab = try expectButtonMsg(tree, "Files", .set_right_panel_tab_files);
    try testing.expect(!files_tab.state.selected);
    const diff_tab = try expectButtonMsg(tree, "Diff", .set_right_panel_tab_diff);
    try testing.expect(diff_tab.state.selected);
    const branch_btn = try expectButtonMsg(tree, "Branch", .set_review_diff_source_branch);
    try testing.expect(!branch_btn.state.selected);
    const uncommitted_btn = try expectButtonMsg(tree, "Uncommitted", .set_review_diff_source_uncommitted);
    try testing.expect(uncommitted_btn.state.selected);
    const staged_btn = try expectButtonMsg(tree, "Staged", .set_review_diff_source_staged);
    try testing.expect(!staged_btn.state.selected);
    const unstaged_btn = try expectButtonMsg(tree, "Unstaged", .set_review_diff_source_unstaged);
    try testing.expect(!unstaged_btn.state.selected);
    const committed_btn = try expectButtonMsg(tree, "Committed", .set_review_diff_source_committed);
    try testing.expect(!committed_btn.state.selected);
    const last_turn_btn = try expectButtonMsg(tree, "Last turn", .set_review_diff_source_last_turn);
    try testing.expect(!last_turn_btn.state.selected);

    try fx.feedLine(spawn.key, "M\tsrc/a.zig\nA\tnew.txt\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_review_diff_status());
    try testing.expect(model.has_review_diff_files());
    try testing.expectEqual(@as(u32, 2), model.review_diff_file_count);
    tree = try buildTree(arena, &model);
    const file_row = try expectButtonMsg(tree, "M src/a.zig", .{ .select_review_diff_file = 1 });
    _ = try expectButtonMsg(tree, "A new.txt", .{ .select_review_diff_file = 2 });
    try testing.expect(findByText(tree.root, .text, review_diff.comparing_status) == null);
    try testing.expect(findByText(tree.root, .scroll_view, "Review files") != null);

    main.update(&model, tree.msgForPointer(file_row.id, .up).?, &fx);
    try testing.expectEqual(@as(u32, 1), model.review_diff_selected_id);
    try testing.expect(model.review_diff_hunk_key >= main.review_diff_hunk_key_first);
    const hunk = findGitReviewHunkSpawnKey(&fx, model.review_diff_hunk_key) orelse return error.MissingReviewHunkSpawn;
    try testing.expect(review_diff.isGitReviewHunkArgv(hunk.argv));
    try testing.expect(!review_diff.isGitReviewDiffArgv(hunk.argv));
    try testing.expectEqualStrings(review_diff.git_head, hunk.argv[7]);
    try testing.expectEqualStrings("--", hunk.argv[8]);
    try testing.expectEqualStrings("src/a.zig", hunk.argv[9]);
    try testing.expect(std.mem.indexOf(u8, hunk.argv[2], "src/a.zig") == null);
    try fx.feedLine(hunk.key, "diff --git a/src/a.zig b/src/a.zig\n+hello\n");
    drainEffects(&model, &fx);
    try fx.feedExit(hunk.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.has_review_diff_hunk());
    try testing.expect(std.mem.indexOf(u8, model.review_diff_hunk(), "+hello") != null);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, model.review_diff_hunk());
    try testing.expect(findByText(tree.root, .scroll_view, "Review hunks") != null);
    const selected_row = try expectButtonMsg(tree, "M src/a.zig", .{ .select_review_diff_file = 1 });
    try testing.expect(selected_row.state.selected);

    main.update(&model, .close_review_diff, &fx);
    try testing.expect(!model.review_diff_active);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .text, "Review") == null);

    main.update(&model, .environment_compare, &fx);
    try testing.expect(model.review_diff_active);
    const empty = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffEmpty;
    try fx.feedExit(empty.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.empty_status, model.review_diff_status());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, review_diff.empty_status);
    try testing.expect(findByText(tree.root, .text, "M src/a.zig") == null);

    main.update(&model, .environment_compare, &fx);
    const fail = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffFail;
    try fx.feedLine(fail.key, "M\tshould-not-show.zig\n");
    drainEffects(&model, &fx);
    try fx.feedExit(fail.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.failed_status, model.review_diff_status());
    try testing.expectEqual(@as(u32, 0), model.review_diff_file_count);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, review_diff.failed_status);
    try testing.expect(findByText(tree.root, .text, "M should-not-show.zig") == null);

    const escape = canvas.WidgetKeyboardEvent{ .phase = .key_down, .key = "escape" };
    main.update(&model, keys.onKey(escape).?, &fx);
    try testing.expect(!model.review_diff_active);

    main.update(&model, .environment_compare, &fx);
    try testing.expect(model.review_diff_active);
    main.update(&model, .{ .select = second }, &fx);
    try testing.expect(!model.review_diff_active);
    try testing.expectEqual(second, model.selected);

    model.selected = first;
    main.update(&model, .environment_compare, &fx);
    try testing.expect(model.review_diff_active);
    const streaming_key = model.review_diff_key;
    model.phase = .streaming;
    main.update(&model, .environment_compare, &fx);
    try testing.expect(model.review_diff_active);
    try testing.expectEqual(streaming_key, model.review_diff_key);
    try testing.expect(model.right_panel_tab_diff());
}

