    try testing.expect(model.has_review_diff_files());
    try testing.expectEqual(@as(u32, 1), model.review_diff_file_count);
    tree = try buildTree(arena, &model);
    _ = try expectButtonMsg(tree, "M committed.zig", .{ .select_review_diff_file = 1 });
    const committed_on = try expectButtonMsg(tree, "Committed", .set_review_diff_source_committed);
    try testing.expect(committed_on.state.selected);
    const branch_off = try expectButtonMsg(tree, "Branch", .set_review_diff_source_branch);
    try testing.expect(!branch_off.state.selected);
    const uncommitted_off = try expectButtonMsg(tree, "Uncommitted", .set_review_diff_source_uncommitted);
    try testing.expect(!uncommitted_off.state.selected);
    const staged_off = try expectButtonMsg(tree, "Staged", .set_review_diff_source_staged);
    try testing.expect(!staged_off.state.selected);
    const unstaged_off = try expectButtonMsg(tree, "Unstaged", .set_review_diff_source_unstaged);
    try testing.expect(!unstaged_off.state.selected);
    const last_turn_off = try expectButtonMsg(tree, "Last turn", .set_review_diff_source_last_turn);
    try testing.expect(!last_turn_off.state.selected);
    try testing.expect(findByText(tree.root, .text, review_diff.comparing_status) == null);

    main.update(&model, tree.msgForPointer(branch_off.id, .up).?, &fx);
    try testing.expectEqual(review_diff.Source.branch, model.review_diff_source);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    const back_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffBack;
    try testing.expectEqualStrings("@{upstream}...HEAD", back_spawn.argv[8]);
    try fx.feedExit(back_spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.empty_status, model.review_diff_status());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, review_diff.empty_status);
    try testing.expect(findByText(tree.root, .text, "M committed.zig") == null);
    const branch_on = try expectButtonMsg(tree, "Branch", .set_review_diff_source_branch);
    try testing.expect(branch_on.state.selected);

    main.update(&model, .set_review_diff_source_committed, &fx);
    const fail_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffCommittedFail;
    try testing.expectEqual(review_diff.argv_len, fail_spawn.argv.len);
    try testing.expectEqualStrings(review_diff.git_committed_range, fail_spawn.argv[8]);
    try fx.feedExit(fail_spawn.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    const main_fail = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffCommittedMain;
    try testing.expectEqualStrings(review_diff.git_committed_range_main, main_fail.argv[8]);
    try fx.feedExit(main_fail.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    const master_fail = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffCommittedMaster;
    try testing.expectEqualStrings(review_diff.git_committed_range_master, master_fail.argv[8]);
    try fx.feedExit(master_fail.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.failed_status, model.review_diff_status());
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, review_diff.failed_status);

    main.update(&model, .close_review_diff, &fx);
    try testing.expect(!model.review_diff_active);
    try testing.expectEqual(review_diff.Source.branch, model.review_diff_source);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Committed") == null);
    try testing.expect(findByText(tree.root, .button, "Last turn") == null);
}

test "Review source row switches Last turn and re-probes rewind sha...HEAD name-status" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/review-last-turn-ui", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("review last turn ui", .fx);
    model.selected = id;
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);

    const sha = "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";
    var range_buf: [review_diff.last_turn_range_len]u8 = undefined;
    const range = review_diff.formatLastTurnRange(sha, &range_buf) orelse return error.MissingLastTurnRange;

    main.update(&model, .environment_compare, &fx);
    try testing.expectEqual(review_diff.Source.uncommitted, model.review_diff_source);
    try testing.expect(model.review_diff_source_uncommitted());
    try testing.expect(!model.review_diff_source_branch());
    try testing.expect(!model.review_diff_source_last_turn());
    const initial_key = model.review_diff_key;
    const initial_spawn = findGitReviewDiffSpawnKey(&fx, initial_key) orelse return error.MissingReviewDiffUncommitted;
    try expectGitReviewUncommittedArgv(initial_spawn.argv);

    var tree = try buildTree(arena, &model);
    const last_turn_off = try expectButtonMsg(tree, "Last turn", .set_review_diff_source_last_turn);
    try testing.expect(!last_turn_off.state.selected);
    main.update(&model, tree.msgForPointer(last_turn_off.id, .up).?, &fx);
    try testing.expect(model.review_diff_active);
    try testing.expectEqual(review_diff.Source.last_turn, model.review_diff_source);
    try testing.expect(model.review_diff_source_last_turn());
    try testing.expect(!model.review_diff_source_branch());
    try testing.expect(!model.review_diff_source_uncommitted());
    try testing.expect(!model.review_diff_source_staged());
    try testing.expect(!model.review_diff_source_unstaged());
    try testing.expect(!model.review_diff_source_committed());
    try testing.expectEqual(@as(u64, 0), model.review_diff_key);
    try testing.expectEqualStrings(review_diff.failed_status, model.review_diff_status());
    try testing.expect(findGitReviewDiffSpawnKey(&fx, initial_key) == null);
    try testing.expect(std.mem.indexOf(u8, model.review_diff_status(), "HEAD~1") == null);
    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, review_diff.failed_status);
    const last_turn_failed = try expectButtonMsg(tree, "Last turn", .set_review_diff_source_last_turn);
    try testing.expect(last_turn_failed.state.selected);

    if (model.sessionById(id)) |session| {
        session.appendRewindRef(sha, rewind.recorded_ref, 1);
    }
    main.update(&model, .set_review_diff_source_last_turn, &fx);
    try testing.expectEqual(review_diff.Source.last_turn, model.review_diff_source);
    try testing.expect(model.review_diff_key >= main.review_diff_key_first);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    const last_turn_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffLastTurn;
    try testing.expect(review_diff.isGitReviewDiffArgv(last_turn_spawn.argv));
    try testing.expectEqual(review_diff.argv_len, last_turn_spawn.argv.len);
    try testing.expectEqualStrings(range, last_turn_spawn.argv[8]);
    try testing.expectEqualStrings("eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee...HEAD", last_turn_spawn.argv[8]);
    try testing.expect(std.mem.indexOf(u8, last_turn_spawn.argv[2], sha) == null);
    try testing.expect(std.mem.indexOf(u8, last_turn_spawn.argv[2], "HEAD~1") == null);
    try testing.expect(last_turn_spawn.key != model.git_numstat_key);

    try fx.feedLine(last_turn_spawn.key, "M\tlast-turn.zig\n");
    drainEffects(&model, &fx);
    try fx.feedExit(last_turn_spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.has_review_diff_files());
    try testing.expectEqual(@as(u32, 1), model.review_diff_file_count);
    tree = try buildTree(arena, &model);
    const file_row = try expectButtonMsg(tree, "M last-turn.zig", .{ .select_review_diff_file = 1 });
    const last_turn_on = try expectButtonMsg(tree, "Last turn", .set_review_diff_source_last_turn);
    try testing.expect(last_turn_on.state.selected);
    const branch_off = try expectButtonMsg(tree, "Branch", .set_review_diff_source_branch);
    try testing.expect(!branch_off.state.selected);
    const uncommitted_off = try expectButtonMsg(tree, "Uncommitted", .set_review_diff_source_uncommitted);
    try testing.expect(!uncommitted_off.state.selected);
    const staged_off = try expectButtonMsg(tree, "Staged", .set_review_diff_source_staged);
    try testing.expect(!staged_off.state.selected);
    const unstaged_off = try expectButtonMsg(tree, "Unstaged", .set_review_diff_source_unstaged);
    try testing.expect(!unstaged_off.state.selected);
    const committed_off = try expectButtonMsg(tree, "Committed", .set_review_diff_source_committed);
    try testing.expect(!committed_off.state.selected);

    main.update(&model, tree.msgForPointer(file_row.id, .up).?, &fx);
    try testing.expectEqual(@as(u32, 1), model.review_diff_selected_id);
    try testing.expect(model.review_diff_hunk_key >= main.review_diff_hunk_key_first);
    const hunk = findGitReviewHunkSpawnKey(&fx, model.review_diff_hunk_key) orelse return error.MissingLastTurnHunkUi;
    try testing.expect(review_diff.isGitReviewHunkArgv(hunk.argv));
    try testing.expectEqualStrings(range, hunk.argv[7]);
    try testing.expectEqualStrings("--", hunk.argv[8]);
    try testing.expectEqualStrings("last-turn.zig", hunk.argv[9]);
    try testing.expect(std.mem.indexOf(u8, hunk.argv[2], sha) == null);

    main.update(&model, tree.msgForPointer(branch_off.id, .up).?, &fx);
    try testing.expectEqual(review_diff.Source.branch, model.review_diff_source);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    const back_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffBack;
    try testing.expectEqualStrings("@{upstream}...HEAD", back_spawn.argv[8]);
    try fx.feedExit(back_spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.empty_status, model.review_diff_status());

    main.update(&model, .set_review_diff_source_last_turn, &fx);
    const fail_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffLastTurnFail;
    try testing.expectEqualStrings(range, fail_spawn.argv[8]);
    try fx.feedExit(fail_spawn.key, 128);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings(review_diff.failed_status, model.review_diff_status());
    try testing.expectEqual(review_diff.Source.last_turn, model.review_diff_source);
    try testing.expectEqual(review_diff.CommittedRange.origin, model.review_diff_committed_range);

    main.update(&model, .close_review_diff, &fx);
    try testing.expect(!model.review_diff_active);
    try testing.expectEqual(review_diff.Source.branch, model.review_diff_source);
    try testing.expectEqual(@as(usize, 0), model.review_diff_last_turn_range_len);
    tree = try buildTree(arena, &model);
    try testing.expect(findByText(tree.root, .button, "Last turn") == null);
}

test "header Environment +/- reuses composer numstat and omits a zero side" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/header-numstat", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("header numstat", .fx);
    model.selected = id;

    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    var spawn = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try testing.expect(!model.has_git_numstat());
    var tree = try buildTree(arena, &model);
    var toolbar = try expectByText(tree.root, .row, "Toolbar");
    var env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    try testing.expect(findByText(env_controls, .row, "header-git-status") == null);
    _ = try expectByText(env_controls, .button, "Environment");

    try fx.feedLine(spawn.key, "3\t1\tsrc/a.zig\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.has_git_numstat());
    try testing.expectEqualStrings("+3 −1", model.git_numstat_label());
    try testing.expectEqualStrings("+3 −1", model.header_git_numstat_label());
    const pending_before_header = fx.pendingSpawnCount();

    tree = try buildTree(arena, &model);
    try testing.expectEqual(pending_before_header, fx.pendingSpawnCount());
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    const header_status = try expectByText(env_controls, .row, "header-git-status");
    const header_plus = try expectByText(header_status, .button, "+3 −1");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(header_plus.id, .up).?);
    try testing.expect(findPressableContaining(header_status, "+3 −1") != null);
    _ = try expectButtonMsg(tree, "+3 −1", .environment_compare);
    _ = try expectByText(env_controls, .button, "Environment");
    _ = try expectByText(tree.root, .text, "+3 −1");
    try testing.expect(!model.git_commit_active);

    git_numstat.refresh(&model, &fx);
    spawn = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try fx.feedLine(spawn.key, "5\t0\tonly-add.txt\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("+5 −0", model.git_numstat_label());
    try testing.expectEqualStrings("+5", model.header_git_numstat_label());

    tree = try buildTree(arena, &model);
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    const header_add = try expectByText(env_controls, .row, "header-git-status");
    const header_add_btn = try expectByText(header_add, .button, "+5");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(header_add_btn.id, .up).?);
    try testing.expect(findByText(header_add, .button, "+5 −0") == null);
    try testing.expect(findByText(header_add, .text, "+5 −0") == null);
    _ = try expectByText(tree.root, .text, "+5 −0");
    _ = try expectByText(env_controls, .button, "Environment");

    git_numstat.refresh(&model, &fx);
    spawn = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try fx.feedLine(spawn.key, "0\t4\tdel.txt\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expectEqualStrings("+0 −4", model.git_numstat_label());
    try testing.expectEqualStrings("−4", model.header_git_numstat_label());

    tree = try buildTree(arena, &model);
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    const header_del = try expectByText(env_controls, .row, "header-git-status");
    const header_del_btn = try expectByText(header_del, .button, "−4");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(header_del_btn.id, .up).?);
    try testing.expect(findByText(header_del, .button, "+0 −4") == null);
    try testing.expect(findByText(header_del, .text, "+0 −4") == null);
    _ = try expectByText(tree.root, .text, "+0 −4");
    _ = try expectByText(env_controls, .button, "Environment");
    try testing.expect(!model.git_commit_active);

    git_numstat.refresh(&model, &fx);
    spawn = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try fx.feedLine(spawn.key, "0\t0\tempty.txt\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(!model.has_git_numstat());
    try testing.expectEqualStrings("", model.header_git_numstat_label());

    tree = try buildTree(arena, &model);
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    try testing.expect(findByText(env_controls, .row, "header-git-status") == null);
    try testing.expect(findByText(tree.root, .text, "+5") == null);
    try testing.expect(findByText(tree.root, .text, "−4") == null);
    _ = try expectByText(env_controls, .button, "Environment");
}

test "header Environment +/- opens the same Review card as Compare" {
    var arena_state = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();
    var project_buf: [256]u8 = undefined;
    const project = try std.fmt.bufPrint(&project_buf, ".zig-cache/tmp/{s}/header-compare", .{tmp.sub_path[0..]});
    try std.Io.Dir.cwd().createDirPath(testing.io, project);

    var fx = Effects.init(testing.allocator);
    defer fx.deinit();
    fx.executor = .fake;

    var model = Model{};
    model.store_io = testing.io;
    const id = model.addSession("header compare", .fx);
    model.selected = id;
    main.update(&model, .{ .project_path_edit = .{ .insert_text = project } }, &fx);
    const numstat = findGitNumstatSpawnKey(&fx, model.git_numstat_key) orelse return error.MissingGitNumstatSpawn;
    try fx.feedLine(numstat.key, "3\t1\tsrc/a.zig\n");
    drainEffects(&model, &fx);
    try fx.feedExit(numstat.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.has_git_numstat());
    try testing.expectEqualStrings("+3 −1", model.header_git_numstat_label());
    try testing.expect(!model.environment_summary_open);
    try testing.expect(!model.review_diff_active);

    var tree = try buildTree(arena, &model);
    var toolbar = try expectByText(tree.root, .row, "Toolbar");
    var env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    const header_status = try expectByText(env_controls, .row, "header-git-status");
    const header_plus = try expectByText(header_status, .button, "+3 −1");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(header_plus.id, .up).?);
    const pending_before_click = fx.pendingSpawnCount();
    main.update(&model, tree.msgForPointer(header_plus.id, .up).?, &fx);
    try testing.expect(!model.environment_summary_open);
    try testing.expect(model.review_diff_active);
    try testing.expect(model.right_panel_open);
    try testing.expect(model.right_panel_tab_diff());
    try testing.expectEqual(review_diff.Source.uncommitted, model.review_diff_source);
    try testing.expect(model.review_diff_key >= main.review_diff_key_first);
    try testing.expectEqualStrings(review_diff.comparing_status, model.review_diff_status());
    try testing.expect(fx.pendingSpawnCount() > pending_before_click);

    const spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffSpawn;
    try testing.expect(review_diff.isGitReviewDiffArgv(spawn.argv));
    try expectGitReviewUncommittedArgv(spawn.argv);

    tree = try buildTree(arena, &model);
    _ = try expectByText(tree.root, .text, "Review");
    _ = try expectByText(tree.root, .text, review_diff.comparing_status);
    _ = try expectButtonMsg(tree, "Cancel", .close_review_diff);
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    _ = try expectByText(env_controls, .button, "+3 −1");
    _ = try expectByText(env_controls, .button, "Environment");

    try fx.feedLine(spawn.key, "M\tsrc/a.zig\n");
    drainEffects(&model, &fx);
    try fx.feedExit(spawn.key, 0);
    drainEffects(&model, &fx);
    try testing.expect(model.has_review_diff_files());
    tree = try buildTree(arena, &model);
    _ = try expectButtonMsg(tree, "M src/a.zig", .{ .select_review_diff_file = 1 });

    main.update(&model, .close_review_diff, &fx);
    try testing.expect(!model.review_diff_active);

    main.update(&model, .toggle_environment_summary, &fx);
    try testing.expect(model.environment_summary_open);
    tree = try buildTree(arena, &model);
    const compare = try expectByText(tree.root, .menu_item, "Compare");
    try testing.expectEqual(Msg.environment_compare, tree.msgForPointer(compare.id, .up).?);
    main.update(&model, tree.msgForPointer(compare.id, .up).?, &fx);
    try testing.expect(!model.environment_summary_open);
    try testing.expect(model.review_diff_active);
    const menu_spawn = findGitReviewDiffSpawnKey(&fx, model.review_diff_key) orelse return error.MissingReviewDiffMenu;
    try testing.expect(review_diff.isGitReviewDiffArgv(menu_spawn.argv));
    try fx.feedExit(menu_spawn.key, 0);
    drainEffects(&model, &fx);
    main.update(&model, .close_review_diff, &fx);
    try testing.expect(!model.review_diff_active);

    tree = try buildTree(arena, &model);
    toolbar = try expectByText(tree.root, .row, "Toolbar");
    env_controls = try expectByText(toolbar, .row, "header-environment-controls");
    const gated = try expectByText(env_controls, .button, "+3 −1");
    model.phase = .streaming;
    main.update(&model, tree.msgForPointer(gated.id, .up).?, &fx);
    try testing.expect(!model.review_diff_active);
    model.phase = .idle;

    model.git_push_key = main.git_push_key_first;
    main.update(&model, tree.msgForPointer(gated.id, .up).?, &fx);
    try testing.expect(!model.review_diff_active);
    try testing.expect(git_checkout.gitMutationInFlight(&model));
}
